class SQLConsoleTests(PolarisTestCase):

    def test_an_account_bound_to_one_authority_is_refused_the_console(self):
        """1.0.0-rc.18. The console runs the query as written, and the row-level policies take
        their scope from a session setting the query itself can change, so a bound admin or
        auditor could clear it and read every authority's rows. The refusal is asserted by its
        effect: the posted query's rows never reach the page."""
        with self.client.session_transaction() as sess:
            sess['operator_agency_id'] = 1
            _bind_account(sess, 1)
        r = self.client.get('/sql')
        self.assertEqual(r.status_code, 403)
        self.assertIn('bound to one authority', r.get_data(as_text=True))
        r = self._post('/sql', data={
            'sql': "SELECT set_config('polaris.operator_agency_id', '', false); "
                   "SELECT individual_id, legal_name FROM Individual ORDER BY individual_id LIMIT 3"})
        self.assertEqual(r.status_code, 403)
        self.assertNotIn('Adrian Vasquez', r.get_data(as_text=True),
                         'a bound account\'s query ran')

    def test_an_unbound_account_keeps_the_console(self):
        """The regression guard: every single-authority instance leaves the binding unset."""
        with self.client.session_transaction() as sess:
            sess.pop('operator_agency_id', None)
            _bind_account(sess, None)
        r = self._post('/sql', data={
            'sql': 'SELECT individual_id, legal_name FROM Individual ORDER BY individual_id LIMIT 3'})
        self.assertEqual(r.status_code, 200)
        self.assertIn('Adrian Vasquez', r.get_data(as_text=True))

    def test_why_a_bound_account_cannot_have_it_a_query_lifts_its_own_scope(self):
        """The fact the refusal rests on, measured as the application role in a read-only
        transaction, which is exactly what the console runs. If this ever stops holding (a
        per-authority database role, say), the refusal can be revisited; until then it is
        what keeps the isolation claim true."""
        conn = psycopg2.connect(**DB_CONFIG)
        try:
            conn.set_session(readonly=True)
            with conn.cursor() as cur:
                cur.execute("SET LOCAL ROLE polaris_app")
                cur.execute("SELECT count(*) FROM IdentityToken")
                everything = cur.fetchone()[0]
                cur.execute("SELECT issuing_agency_id FROM IdentityToken "
                            "GROUP BY 1 ORDER BY count(*) LIMIT 1")
                row = cur.fetchone()
                if row is None:
                    self.fail('the fixture has no credentials to scope')
                cur.execute("SELECT set_config('polaris.operator_agency_id', %s, false)",
                            (str(row[0]),))
                cur.execute("SELECT count(*) FROM IdentityToken")
                scoped = cur.fetchone()[0]
                cur.execute("SELECT set_config('polaris.operator_agency_id', '', false); "
                            "SELECT count(*) FROM IdentityToken")
                lifted = cur.fetchone()[0]
        finally:
            conn.rollback()
            conn.close()
        self.assertLess(scoped, everything, 'control: the scope must hide something')
        self.assertEqual(lifted, everything,
                         'the query cleared its own scope; if it no longer can, revisit the refusal')

    def test_console_renders(self):
        r = self.client.get('/sql')
        self.assertEqual(r.status_code, 200)
        self.assertHTML(r, 'SQL Console', 'Example Queries')

    def test_simple_select_works(self):
        r = self._post('/sql', data={
            'sql': 'SELECT individual_id, legal_name FROM Individual ORDER BY individual_id LIMIT 3'
        })
        self.assertEqual(r.status_code, 200)
        self.assertHTML(r, 'Adrian Vasquez', 'Maria Santos', 'James Chen')

    def test_update_blocked_by_whitelist(self):
        r = self._post('/sql', data={
            'sql': "UPDATE Individual SET legal_name='X' WHERE individual_id=1"
        })
        self.assertEqual(r.status_code, 200)
        self.assertHTML(r, 'read-only', 'Only SELECT and WITH')

    def test_drop_blocked_by_whitelist(self):
        r = self._post('/sql', data={
            'sql': 'DROP TABLE Individual'
        })
        self.assertEqual(r.status_code, 200)
        self.assertHTML(r, 'read-only')

    def test_with_query_works(self):
        r = self._post('/sql', data={
            'sql': 'WITH t AS (SELECT 1 AS n) SELECT * FROM t'
        })
        self.assertEqual(r.status_code, 200)
        # Should have rendered a result table

    def test_data_modifying_cte_refused_by_db_readonly(self):
        """The keyword whitelist accepts WITH, so a data-modifying CTE
        (`WITH x AS (DELETE ... RETURNING *) SELECT * FROM x`) slips straight
        past it. The real boundary is the read-only transaction: Postgres
        refuses the write itself. This discriminates cleanly — on a writable
        transaction this 0-row CTE-DELETE would simply succeed and render an
        empty result; refused, it surfaces the sanitized DB-error message. We
        target a non-existent id so nothing is mutated even under regression."""
        r = self._post('/sql', data={
            'sql': ("WITH gone AS (DELETE FROM Individual WHERE individual_id = -99999 "
                    "RETURNING individual_id) SELECT * FROM gone"),
        })
        self.assertEqual(r.status_code, 200)
        body = r.get_data(as_text=True).lower()
        self.assertIn('database error', body,
                      "a data-modifying CTE must be refused by the read-only "
                      "transaction, not executed")

    def test_oversized_query_rejected(self):
        """Queries over the length cap must be rejected before execution."""
        # 5001 chars of SELECT 1; clearly over the 5000 cap
        big_sql = "SELECT 1 -- " + ("X" * 5001)
        r = self._post('/sql', data={'sql': big_sql})
        self.assertEqual(r.status_code, 200)
        self.assertHTML(r, 'exceeds the', 'character limit')

    def test_explain_analyze_button(self):
        """EXPLAIN ANALYZE button surfaces query plans."""
        r = self._post('/sql', data={
            'sql': 'SELECT * FROM Individual',
            'explain': '1',
        })
        self.assertEqual(r.status_code, 200)
        body = r.get_data(as_text=True)
        # EXPLAIN output typically contains "Seq Scan" or "rows="
        self.assertTrue('Scan' in body or 'rows=' in body or 'cost=' in body,
                        "Expected EXPLAIN output to contain query-plan keywords")
        self.assertIn('Showing query plan', body)

    def test_runaway_query_times_out(self):
        """A query that would take much longer than 5s should be cancelled
        cleanly with a user-readable message, not a stack trace."""
        # pg_sleep(10) blocks the connection for 10 seconds — guaranteed to
        # exceed the 5s statement_timeout. We expect a clean timeout message.
        slow_sql = "SELECT pg_sleep(10)"
        r = self._post('/sql', data={'sql': slow_sql})
        self.assertEqual(r.status_code, 200)
        body = r.get_data(as_text=True)
        # Either the timeout message rendered, or — if the test runner is
        # remarkably fast — the query completed. Either way: no 500.
        self.assertNotIn('Internal server error', body)
        # And specifically, the timeout error is what we expect
        self.assertIn('timed out', body.lower())


class BoundedConsoleTests(PolarisTestCase):
    """lab/strategy/008, step 4. The SQL console reads a query's rows from a server-side cursor
    and shows at most sql_console.SQL_MAX_ROWS of them, saying when there were more; a web
    request's statements end before its worker does."""

    def test_a_large_result_shows_its_first_rows_and_says_so(self):
        import sql_console
        with patch.object(sql_console, 'SQL_MAX_ROWS', 3):
            r = self._post('/sql', data={'sql': 'SELECT n FROM generate_series(1, 10) n ORDER BY n'})
        self.assertEqual(r.status_code, 200)
        body = r.get_data(as_text=True)
        self.assertIn('the first 3 rows', body)
        self.assertIn('returned more than 3 rows', body)
        cells = re.findall(r'<td[^>]*>\s*(.*?)\s*</td>', body, re.S)
        self.assertEqual(cells, ['1', '2', '3'])
        r = self._post('/sql', data={'sql': 'SELECT n FROM generate_series(1, 2) n'})
        self.assertNotIn('returned more than', r.get_data(as_text=True), 'a small result is whole')

    def test_the_rows_shown_are_all_that_leave_the_database(self):
        """A hundred million rows, produced lazily by a cross join: read whole (fetchall), the
        query runs into the console's timeout; read through the cursor, the page has its rows at
        once. The effect, not the code shape, is what is asserted."""
        r = self._post('/sql', data={
            'sql': 'SELECT a.n, b.m FROM generate_series(1, 100000) a(n), generate_series(1, 1000) b(m)'})
        self.assertEqual(r.status_code, 200)
        body = r.get_data(as_text=True)
        self.assertNotIn('timed out', body.lower())
        self.assertIn('returned more than', body)

    def test_a_request_connection_ends_its_statements_before_its_worker_does(self):
        def timeout_ms(conn):
            with conn.cursor() as cur:
                cur.execute("SELECT (EXTRACT(EPOCH FROM current_setting('statement_timeout')::interval)"
                            " * 1000)::bigint AS ms")
                return cur.fetchone()['ms']
        with flask_app.app.test_request_context('/'):
            conn = flask_app.get_db()
            try:
                self.assertEqual(timeout_ms(conn), flask_app.WEB_STATEMENT_TIMEOUT_MS)
            finally:
                conn.close()
        conn = flask_app.get_db()            # outside a request: a job, the CLI's own connection
        try:
            self.assertEqual(timeout_ms(conn), 0, 'a connection outside a request is not held to it')
        finally:
            conn.close()
        # The effect: a statement past the bound is ended by the database.
        with patch.object(flask_app, 'WEB_STATEMENT_TIMEOUT_MS', 200), \
                flask_app.app.test_request_context('/'):
            with self.assertRaises(psycopg2.errors.QueryCanceled):
                flask_app.query("SELECT pg_sleep(2)", fetch='one')

    def test_the_console_runs_one_statement(self):
        """A second statement could lift the console's limit: SET is permitted in a read-only
        transaction, and one execute() runs every statement in its text. The text is refused
        before a connection opens, and a semicolon inside a string, a comment or a dollar-quoted
        body is not a separator."""
        import sql_console
        # The console's own connection points nowhere: had the text been sent, the page would
        # carry a connection error instead of the refusal. No other connection is touched.
        with patch.object(sql_console, 'DB_CONFIG', dict(flask_app.DB_CONFIG, port=1, connect_timeout=1)):
            r = self._post('/sql', data={'sql': "SELECT 1; SET statement_timeout = 0; SELECT pg_sleep(30)"})
        body = r.get_data(as_text=True)
        self.assertIn('One statement at a time', body)
        self.assertNotIn('<table class="data">', body)
        r = self._post('/sql', data={'sql': "SELECT ';' AS semicolon -- ; a comment\n"})
        self.assertEqual(re.findall(r'<td[^>]*>\s*(.*?)\s*</td>', r.get_data(as_text=True), re.S), [';'])
        for text, n in (("SELECT 1;", 1), ("SELECT 'a'';b'", 1), ("SELECT E'a\\';b'", 1),
                        ("SELECT 'a\\'; SELECT 2", 2), ("SELECT $t$ ; $t$", 1),
                        ("SELECT 1 /* ; /* ; */ ; */", 1), ('SELECT "a;b"', 1),
                        ("SELECT a$b; SELECT 2", 2), ("SELECT 1; -- after", 1), ("SELECT 'open; x", 1)):
            with self.subTest(text=text):
                self.assertEqual(sql_console.statement_count(text), n)

    def test_the_limit_is_set_again_before_the_rows_are_read(self):
        """A server-side cursor's query runs at the FETCH, after the DECLARE that carried the
        text. Were a second statement ever let through (the lexer above is the first guard), a
        SET riding with the DECLARE would otherwise lift the limit for the query itself."""
        import sql_console
        with patch.object(sql_console, 'statement_count', return_value=1):
            r = self._post('/sql', data={'sql': "SELECT pg_sleep(8); SET statement_timeout = 0"})
        # Lifted, the sleep would finish and its row would show; held, the database cancels it.
        self.assertIn('timed out', r.get_data(as_text=True).lower())

    def test_the_bound_follows_the_worker_timeout(self):
        for env, expected in (({}, 28_000), ({'POLARIS_TIMEOUT': '120'}, 118_000),
                              ({'POLARIS_TIMEOUT': '2'}, 1_000),
                              ({'POLARIS_TIMEOUT': '30', 'POLARIS_DB_STATEMENT_TIMEOUT_MS': '9000'}, 9_000)):
            with self.subTest(env=env):
                self.assertEqual(flask_app._web_statement_timeout_ms(env), expected)


