class BoundOperatorRouteIsolationTests(PolarisTestCase):
    """The routes themselves, run AS the application role by an operator bound to authority 1,
    asked for authority 3's credential (2026-09-25). Every other test in this file connects as
    the schema owner, whom row-level security does not bind, so no route test had ever gone
    through the policies; the rc.41 view leak was invisible to all of them. The rule is the
    effect: the other authority's credential value never reaches a page."""

    def setUp(self):
        super().setUp()
        from unittest import mock
        app_cfg = dict(user='polaris_app',
                       password=os.environ.get('POLARIS_APP_TEST_PASSWORD', 'polaris_dev_password'))
        try:
            psycopg2.connect(**dict(flask_app.DB_CONFIG, **app_cfg)).close()
        except psycopg2.OperationalError as exc:
            if os.environ.get('CI'):
                self.fail('polaris_app unreachable in CI: %s' % exc)
            self.skipTest('polaris_app unreachable: %s' % exc)
        row = _sql("SELECT token_value, issuing_agency_id FROM IdentityToken WHERE token_id = 2",
                   fetch='one')
        self.assertNotEqual(row['issuing_agency_id'], 1, 'fixture: token 2 is another authority\'s')
        self.foreign_value = row['token_value']
        self.own_value = _sql("SELECT token_value FROM IdentityToken WHERE issuing_agency_id = 1 "
                              "AND token_id = 3", fetch='one')['token_value']
        # The binding is an administrator's act, made as the owner, before the application is
        # switched to its own role (which, since 2026-09-27, cannot change an account).
        with self.client.session_transaction() as sess:
            sess['operator_agency_id'] = 1
            _bind_account(sess, 1)
        patcher = mock.patch.dict(flask_app.DB_CONFIG, app_cfg)
        patcher.start()
        self.addCleanup(patcher.stop)

    def test_a_lookup_answers_another_authoritys_credential_as_one_that_does_not_exist(self):
        """lab/strategy/008 step 2: the lookup reads through the same policies, so another
        authority's credential, asked for by its value, gets exactly the answer a value nobody
        holds gets: the lookup is not an oracle for another authority's records."""
        csrf = self._csrf_token_from('/uc8/revoke')

        def find(text):
            return self.client.post('/find/credential', data={'credential': text, 'next': 'uc8_revoke',
                                                              'csrf_token': csrf})
        hidden, absent = find(self.foreign_value), find('TKN-NOBODY-HAS-THIS')
        self.assertEqual((hidden.status_code, absent.status_code), (404, 404),
                         hidden.get_data(as_text=True)[:300])

        def page(r, typed):
            return re.sub(r'name="csrf_token" value="[^"]*"', '', r.get_data(as_text=True)).replace(typed, 'X')
        self.assertEqual(page(hidden, self.foreign_value), page(absent, 'TKN-NOBODY-HAS-THIS'))
        self.assertEqual(find(self.own_value).status_code, 302,
                         'control: the operator finds its own authority\'s credential')

    def test_no_form_opens_on_another_authoritys_credential(self):
        for path in ('/uc4/activate-reserve', '/uc5/bind-device', '/uc6/migrate', '/uc8/revoke',
                     '/verifications/new'):
            with self.subTest(form=path):
                r = self.client.get(path + '?token_id=2')
                self.assertEqual(r.status_code, 404)
                body = r.get_data(as_text=True)
                self.assertNotIn(self.foreign_value, body)
                self.assertIn('No credential matches #2', body)
                own = self.client.get(path + '?token_id=3')
                self.assertEqual(own.status_code, 200, 'control: its own credential opens')
                self.assertIn(self.own_value, own.get_data(as_text=True))

    def test_no_wallet_offer_for_a_credential_the_operator_cannot_see(self):
        # Row-level security hides token 2 from an operator bound to authority 1, and hidden is
        # not "not found" (rc.43): the offer route answers 403 before it looks for a key.
        r = self._post('/tokens/2/wallet-offer', csrf_from='/tokens')
        self.assertEqual(r.status_code, 403, r.get_data(as_text=True)[:300])
        self.assertNotIn(self.foreign_value, r.get_data(as_text=True))

    def test_the_investigate_card_is_scoped(self):
        self.assertEqual(self.client.get('/investigate/token/2').status_code, 404)
        own = self.client.get('/investigate/token/3')
        self.assertEqual(own.status_code, 200, 'control: the operator\'s own credential shows')
        self.assertIn(self.own_value, own.get_data(as_text=True))

    def test_no_token_route_shows_another_authoritys_credential(self):
        routes = sorted({r.rule for r in flask_app.app.url_map.iter_rules()
                         if 'GET' in r.methods and len(r.arguments) == 1
                         and any(a in r.arguments for a in ('tok_id', 'token_id'))})
        self.assertGreaterEqual(len(routes), 3, 'the sweep must find the token routes')
        leaked = []
        for rule in routes:
            url = rule.replace('<int:tok_id>', '2').replace('<int:token_id>', '2')
            body = self.client.get(url).get_data(as_text=True)
            if self.foreign_value in body:
                leaked.append(url)
        self.assertEqual(leaked, [], 'another authority\'s credential reached these pages')

    def test_no_route_acts_on_another_authoritys_credential(self):
        """1.0.0-rc.43. The token gate returned "not denied" when the lookup found no row, and
        for a bound operator a hidden row is not a missing one. rc.40 made uc5_bind_device
        SECURITY DEFINER, so the procedure then saw what the gate could not: a device was bound
        to authority 3's credential by an operator bound to authority 1 (measured, 2 -> 3
        bindings). The rule is the effect: nothing about token 2 changes."""
        def state():
            return _sql("SELECT t.status, t.algorithm_id, "
                        "(SELECT count(*) FROM DeviceBinding d WHERE d.token_id = 2) AS devices, "
                        "(SELECT count(*) FROM IdentityToken s WHERE s.predecessor_token_id = 2) AS successors "
                        "FROM IdentityToken t WHERE t.token_id = 2", fetch='one')
        attempts = [
            ('/uc5/bind-device', {'token_id': '2', 'device_type': 'PHONE',
                                  'device_fingerprint': 'cd' * 16, 'binding_method': 'SECURE_ENCLAVE',
                                  'validity_months': '12'}, None),
            ('/uc6/migrate', {'token_id': '2', 'new_algorithm': '2'}, None),
            ('/tokens/2/transition', {'new_status': 'DORMANT'}, '/tokens'),
            ('/tokens/2/delete', {}, '/tokens'),
        ]
        # Each attempt from the same starting state, so one route's change cannot be charged
        # to the next. Measured one at a time on rc.42: only /uc5/bind-device changed token 2;
        # the others are here because their gates had the same shape.
        for path, data, csrf_from in attempts:
            with self.subTest(route=path):
                reload_sample_data()        # which also ends the session: sign in again
                self.client = flask_app.app.test_client()
                self._login('admin')
                with self.client.session_transaction() as sess:
                    sess['operator_agency_id'] = 1
                    _bind_account(sess, 1)
                before = state()
                self.assertIsNotNone(before, 'fixture: token 2 exists')
                r = self._post(path, data=data, csrf_from=csrf_from)
                self.assertEqual(state(), before, '%s changed another authority\'s credential '
                                 '(HTTP %d)' % (path, r.status_code))

    def test_no_page_shows_another_authoritys_credential(self):
        """Every GET page that takes no argument. With IdentityToken's policy disabled this
        names /tokens and the four use-case forms that list credentials (measured
        2026-09-25), so it is a sweep that can fail; with the policy, none."""
        served, leaked = 0, []
        for r in sorted(flask_app.app.url_map.iter_rules(), key=lambda r: r.rule):
            if ('GET' not in r.methods or r.arguments or r.rule.startswith('/static')
                    or 'logout' in r.rule):
                continue
            resp = self.client.get(r.rule)
            served += resp.status_code == 200
            if self.foreign_value in resp.get_data(as_text=True):
                leaked.append(r.rule)
        self.assertGreaterEqual(served, 30, 'the sweep must reach the pages')
        self.assertEqual(leaked, [], 'another authority\'s credential reached these pages')


class RateWindowTests(unittest.TestCase):
    """1.0.0-rc.34. The rolling rate moved its window only when an event arrived, so after a
    burst it reported the burst as the current rate for as long as nothing else happened."""

    def _window(self):
        import observability
        clock = [1000]
        w = observability.RateWindow(window_minutes=5)
        w._minute_now = lambda: clock[0]
        w._current_minute = clock[0]
        return w, clock

    def test_a_burst_ages_out_of_the_rate_without_new_events(self):
        w, clock = self._window()
        w.inc(100)
        clock[0] = 1001
        self.assertEqual(w.rate_per_minute(), 50.0, 'control: the burst is in the window')
        clock[0] = 1060
        self.assertEqual(w.rate_per_minute(), 0.0,
                         'an hour after the last failure the rate still reported the burst')

    def test_events_after_silence_count_normally(self):
        w, clock = self._window()
        w.inc(10)
        clock[0] = 1030
        w.inc(6)
        self.assertEqual(w.rate_per_minute(), 1.0)


class MetricsMultiprocessTests(unittest.TestCase):
    """v9.120: under gunicorn's multiple workers, /metrics must AGGREGATE every
    worker's counters (PROMETHEUS_MULTIPROC_DIR) — not report only the worker
    that happened to serve the scrape (a 4x undercount under 4 workers). Proven
    across REAL processes: one process increments a counter and exits, a
    separate process scrapes /metrics and must see that increment."""

    def _mp_env(self, mpdir):
        env = {k: v for k, v in os.environ.items()}
        env['PROMETHEUS_MULTIPROC_DIR'] = mpdir
        env.setdefault('POLARIS_SECRET_KEY', 'test-mp-32-bytes-secret-not-real!')
        env.setdefault('POLARIS_DB_HOST', 'localhost')
        env.setdefault('POLARIS_DB_NAME', 'polaris_test')
        return env

    def test_metrics_aggregate_across_separate_processes(self):
        import subprocess, tempfile, shutil
        mpdir = tempfile.mkdtemp()
        cwd = os.path.dirname(os.path.abspath(__file__))
        env = self._mp_env(mpdir)
        try:
            # Worker process: increment the request counter by 7, then exit.
            subprocess.check_call(
                [sys.executable, '-c',
                 "import app; app._METRICS_REQUESTS.labels("
                 "route='/mp', method='GET', status='200').inc(7)"],
                cwd=cwd, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            # A SEPARATE process scrapes /metrics; the MultiProcessCollector must
            # surface the other worker's increment.
            out = subprocess.check_output(
                [sys.executable, '-c',
                 "import app; b = app.app.test_client().get('/metrics').get_data(as_text=True);"
                 "print(next((l for l in b.splitlines() "
                 "if l.startswith('polaris_requests_total') and 'route=\"/mp\"' in l), 'MISSING'))"],
                cwd=cwd, env=env, text=True, stderr=subprocess.DEVNULL)
            self.assertNotIn('MISSING', out,
                '/metrics did not surface a counter incremented in another worker process')
            self.assertIn(' 7.0', out,
                f'/metrics did not aggregate the other worker increment: {out!r}')
        finally:
            shutil.rmtree(mpdir, ignore_errors=True)


