class F05_ProductionSecretGuardTests(unittest.TestCase):
    """F-05: Refuse to start in prod with default secret. CWE-798 / OWASP A05."""

    def test_dev_default_secret_rejected_in_production(self):
        """Setting POLARIS_ENV=production with the dev secret must exit."""
        import subprocess
        # Run app.py and expect it to exit with code 2 (the subprocess sets the env inline)
        proc = subprocess.run(
            [sys.executable, '-c',
             'import os, sys; sys.path.insert(0, "."); '
             'os.environ["POLARIS_ENV"]="production"; '
             'os.environ["POLARIS_SECRET_KEY"]="dev-key-change-in-production"; '
             'import app'],
            cwd=os.path.dirname(os.path.abspath(__file__)),
            capture_output=True, text=True, timeout=10
        )
        self.assertEqual(proc.returncode, 2,
                         f"Expected exit 2; got {proc.returncode}. "
                         f"stderr: {proc.stderr[:300]}")
        self.assertIn('FATAL', proc.stderr)

    def _prod_import(self, extra_env):
        """Import app.py in a subprocess under POLARIS_ENV=production with a real
        secret, plus extra_env. Returns the completed process."""
        import subprocess
        setup = ('import os, sys; sys.path.insert(0, "."); '
                 'os.environ["POLARIS_ENV"]="production"; '
                 'os.environ["POLARIS_SECRET_KEY"]="' + ('a1b2' * 16) + '"; '
                 # Start from a clean slate so a stray parent value does not trip
                 # a guard the test did not intend.
                 'os.environ.pop("POLARIS_DURESS_SYNC", None); '
                 'os.environ.pop("POLARIS_DB_SSLMODE", None); '
                 'os.environ.pop("POLARIS_DB_SSLROOTCERT", None); ')
        for k, v in extra_env.items():
            setup += 'os.environ["%s"]="%s"; ' % (k, v)
        setup += 'import app'
        return subprocess.run(
            [sys.executable, '-c', setup],
            cwd=os.path.dirname(os.path.abspath(__file__)),
            capture_output=True, text=True, timeout=15)

    def test_plaintext_sslmode_rejected_in_production(self):
        """v9.129: a plaintext-capable POLARIS_DB_SSLMODE must refuse to boot in prod."""
        proc = self._prod_import({'POLARIS_DB_SSLMODE': 'prefer'})
        self.assertEqual(proc.returncode, 2, f"stderr: {proc.stderr[:400]}")
        self.assertIn('FATAL', proc.stderr)
        self.assertIn('POLARIS_DB_SSLMODE', proc.stderr)

    def test_duress_sync_rejected_in_production(self):
        """v9.129: POLARIS_DURESS_SYNC=1 (timing side-channel) must refuse to boot in prod."""
        proc = self._prod_import({'POLARIS_DB_SSLMODE': 'require',
                                  'POLARIS_DURESS_SYNC': '1'})
        self.assertEqual(proc.returncode, 2, f"stderr: {proc.stderr[:400]}")
        self.assertIn('FATAL', proc.stderr)
        self.assertIn('POLARIS_DURESS_SYNC', proc.stderr)

    def test_require_sslmode_boots_in_production(self):
        """The guards are not over-eager: require + no duress-sync must NOT exit
        for a TLS/duress reason (it may exit 0 or fail later on the DB, but not
        with our FATAL guard messages)."""
        proc = self._prod_import({'POLARIS_DB_SSLMODE': 'require'})
        self.assertNotIn('POLARIS_DB_SSLMODE', proc.stderr)
        self.assertNotIn('POLARIS_DURESS_SYNC', proc.stderr)

    def test_verify_ca_without_sslrootcert_rejected_in_production(self):
        """v9.132: verify-ca needs a pinned CA; without POLARIS_DB_SSLROOTCERT it
        cannot verify the peer, so it must refuse to boot in production."""
        proc = self._prod_import({'POLARIS_DB_SSLMODE': 'verify-ca'})
        self.assertEqual(proc.returncode, 2, f"stderr: {proc.stderr[:400]}")
        self.assertIn('FATAL', proc.stderr)
        self.assertIn('POLARIS_DB_SSLROOTCERT', proc.stderr)

    def test_typo_sslmode_rejected_in_production(self):
        """v9.132: the whitelist rejects a typo'd mode ('verifyca') that the old
        blacklist would have let through."""
        proc = self._prod_import({'POLARIS_DB_SSLMODE': 'verifyca'})
        self.assertEqual(proc.returncode, 2, f"stderr: {proc.stderr[:400]}")
        self.assertIn('FATAL', proc.stderr)
        self.assertIn('POLARIS_DB_SSLMODE', proc.stderr)


class ConnectionPoolTests(PolarisTestCase):
    """Lab record 017, phase 2d: a pooled connection carries nothing from one request to the next."""

    def _pool(self, size=2):
        return flask_app._ConnectionPool(size, flask_app.DB_CONFIG)

    def test_a_reused_connection_carries_no_operator_scope(self):
        pool = self._pool()
        c1 = pool.getconn()
        pid = c1.info.backend_pid
        with c1.cursor() as cur:
            cur.execute("SELECT set_config('polaris.operator_agency_id', '2', false)")
        c1.commit()  # as a request does: committed, the setting lives as long as the session
        c1.close()
        c2 = pool.getconn()
        try:
            self.assertEqual(c2.info.backend_pid, pid, "the pool must reuse the connection")
            with c2.cursor() as cur:
                cur.execute("SELECT current_setting('polaris.operator_agency_id', true) AS v")
                self.assertIn(cur.fetchone()['v'], (None, ''),
                              "a reused connection carried the previous operator's scope")
        finally:
            c2.close()

    def test_session_and_transaction_state_do_not_survive_a_return(self):
        pool = self._pool()
        c1 = pool.getconn()
        with c1.cursor() as cur:
            cur.execute("CREATE TEMP TABLE pool_probe_temp (x int)")
        c1.commit()  # a committed temp table lives as long as the session
        with c1.cursor() as cur:
            cur.execute("CREATE TEMP TABLE pool_probe_uncommitted (x int)")
        c1.close()  # this one never committed: only the rollback on return removes it
        c2 = pool.getconn()
        try:
            with c2.cursor() as cur:
                cur.execute("SELECT to_regclass('pg_temp.pool_probe_temp') AS t, "
                            "to_regclass('pg_temp.pool_probe_uncommitted') AS u")
                row = cur.fetchone()
            self.assertIsNone(row['t'], "a session's temp table survived the return")
            self.assertIsNone(row['u'], "an uncommitted transaction survived the return")
        finally:
            c2.close()

    def test_a_broken_connection_is_replaced(self):
        pool = self._pool()
        c1 = pool.getconn()
        pid = c1.info.backend_pid
        c1.close()
        killer = psycopg2.connect(**flask_app.DB_CONFIG)
        try:
            with killer.cursor() as cur:
                cur.execute("SELECT pg_terminate_backend(%s)", (pid,))
            killer.commit()
        finally:
            killer.close()
        c2 = pool.getconn()
        try:
            with c2.cursor() as cur:
                cur.execute("SELECT 1 AS one")
                self.assertEqual(cur.fetchone()['one'], 1)
            self.assertNotEqual(c2.info.backend_pid, pid)
        finally:
            c2.close()

    def test_a_pool_inherited_across_a_fork_is_not_used(self):
        pool = self._pool()
        c1 = pool.getconn()
        pid = c1.info.backend_pid
        c1.close()
        pool._pid = -1  # as if this process were a fork of the one that filled the pool
        c2 = pool.getconn()
        try:
            self.assertNotEqual(c2.info.backend_pid, pid, "a forked worker reused its parent's socket")
        finally:
            c2.close()

    def test_a_changed_configuration_never_reuses_another_roles_connection(self):
        """The role a connection was opened as is the role row-level security applies to: when
        the configuration names polaris_app, no connection opened as the owner may serve it."""
        from unittest import mock
        with mock.patch.object(flask_app, 'DB_POOL_SIZE', 2):
            flask_app._DB_POOLS.clear()
            owner = flask_app.get_db()
            with owner.cursor() as cur:
                cur.execute("SELECT current_user AS u")
                owner_role = cur.fetchone()['u']
            owner.close()  # idle in the owner's pool
            if owner_role == 'polaris_app':
                flask_app._DB_POOLS.clear()
                self.skipTest("this run is already polaris_app; the owner-to-app direction runs "
                              "in the owner suite")
            app_cfg = dict(user='polaris_app',
                           password=os.environ.get('POLARIS_APP_TEST_PASSWORD', 'polaris_dev_password'))
            try:
                psycopg2.connect(**dict(flask_app.DB_CONFIG, **app_cfg)).close()
            except psycopg2.OperationalError as exc:
                self.skipTest('polaris_app unreachable: %s' % exc)
            with mock.patch.dict(flask_app.DB_CONFIG, app_cfg):
                conn = flask_app.get_db()
                try:
                    with conn.cursor() as cur:
                        cur.execute("SELECT current_user AS u")
                        role = cur.fetchone()['u']
                finally:
                    conn.close()
            flask_app._DB_POOLS.clear()
        self.assertNotEqual(owner_role, 'polaris_app')
        self.assertEqual(role, 'polaris_app', "a request configured as polaris_app was served as %s" % role)

    def test_the_pool_is_off_by_default(self):
        self.assertEqual(flask_app._db_pool_size({}), 0)
        self.assertEqual(flask_app._db_pool_size({'POLARIS_DB_POOL_SIZE': ''}), 0)
        self.assertEqual(flask_app._db_pool_size({'POLARIS_DB_POOL_SIZE': '4'}), 4)


class F06_CookieHardeningTests(PolarisTestCase):
    """F-07: Cookie attributes Secure / HttpOnly / SameSite. CWE-614, CWE-1004."""

    def test_session_cookie_httponly(self):
        """The session cookie must have HttpOnly to prevent JS theft."""
        # Use the cookie jar from the client, which exposes flags as attributes
        # of the cookie object
        r = self.client.post('/login', data={
            'username':'admin', 'password':'Admin@123!'
        })
        # Find the polaris_session cookie in the response
        for cookie in self.client.cookie_jar if hasattr(self.client, 'cookie_jar') else []:
            if cookie.name == 'polaris_session':
                # Werkzeug's test client cookies expose flags via _rest
                break
        # Alternative: parse the Set-Cookie header
        set_cookie = r.headers.get('Set-Cookie', '')
        if 'polaris_session' in set_cookie:
            self.assertIn('HttpOnly', set_cookie)
            self.assertIn('SameSite=Lax', set_cookie)


class F08_ErrorMessageSanitizationTests(PolarisTestCase):
    """F-08: DB errors don't leak SQL fragments. CWE-209 / OWASP A09."""

    def test_unknown_error_returns_generic_message(self):
        """Unhandled DB errors yield a generic message, not internals."""
        # Call db_error_to_message directly with a fabricated unknown error
        from app import db_error_to_message
        class FakeErr:
            def __str__(self):
                return ('ERROR:  some internal column "secret_field" something\n'
                        'DETAIL:  internal sql here SELECT * FROM secret_table')
        msg = db_error_to_message(FakeErr())
        # Must NOT leak the internal fragments
        self.assertNotIn('secret_field', msg)
        self.assertNotIn('secret_table', msg)
        self.assertNotIn('SELECT *', msg)

    def test_known_constraint_returns_friendly_message(self):
        """Known constraints still return readable user messages."""
        from app import db_error_to_message
        class FakeErr:
            def __str__(self):
                return ('ERROR:  duplicate key value violates unique constraint '
                        '"uq_one_active_per_person"')
        msg = db_error_to_message(FakeErr())
        self.assertIn('Cannot create a second ACTIVE token', msg)


class F11_AuditLoggingTests(PolarisTestCase):
    """F-11: Authentication events recorded in AuthAuditLog."""

    def _get_event_count(self, event_type):
        conn = psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG)
        with conn.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) AS n FROM AuthAuditLog WHERE event_type=%s",
                (event_type,)
            )
            n = cur.fetchone()['n']
        conn.close()
        return n

    def test_login_success_audited(self):
        before = self._get_event_count('LOGIN_SUCCESS')
        self._logout()
        self._login('operator')
        after = self._get_event_count('LOGIN_SUCCESS')
        self.assertGreater(after, before)

    def test_authz_denial_audited(self):
        """Forbidden-by-role accesses are logged."""
        self._logout()
        self._login('operator')  # operator has no /individuals/new
        before = self._get_event_count('AUTHZ_DENIED')
        r = self.client.get('/individuals/new')
        self.assertEqual(r.status_code, 403)
        after = self._get_event_count('AUTHZ_DENIED')
        self.assertEqual(after, before + 1)

    def test_audit_log_is_append_only(self):
        """Confirm UPDATE/DELETE on AuthAuditLog is rejected by trigger."""
        conn = psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG)
        with conn.cursor() as cur:
            with self.assertRaises(psycopg2.Error):
                cur.execute("UPDATE AuthAuditLog SET detail='tampered' "
                            "WHERE audit_id = (SELECT MIN(audit_id) FROM AuthAuditLog)")
        conn.rollback()
        with conn.cursor() as cur:
            with self.assertRaises(psycopg2.Error):
                cur.execute("DELETE FROM AuthAuditLog "
                            "WHERE audit_id = (SELECT MIN(audit_id) FROM AuthAuditLog)")
        conn.rollback()
        conn.close()


class RoleBasedAccessControlTests(PolarisTestCase):
    """Role enforcement across the route matrix."""

    # v9.417: ROLE_MATRIX and the walk over it are gone. It named 10 paths
    # against 27 routes carrying @require_role, with a comment saying the sets
    # had to match the decorators, and nothing compared them.
    # RouteGuardMatrixTests reads the allowed set off each route instead, and
    # pins the whole map so a route becoming more permissive fails.


    def test_navigation_only_shows_allowed_links(self):
        """The nav bar is role-gated — operator shouldn't see SQL Console."""
        self._logout()
        self._login('operator')
        r = self.client.get('/dashboard')
        # Operator can't use SQL console, so the nav link shouldn't appear
        # (The role-based template hides it.)
        self.assertNotHTML(r, '>SQL console<')
        # v8.14 iteration 11: UC-* nav items moved into a <details>
        # dropdown menu; operator sees UC-1 / UC-4 / UC-5 / UC-6 / UC-8 / UC-9.
        # v8.15 R11-6: UC-8 (bounded revocation) added to the operator set.
        # v8.17 R11-2: UC-9 (recovery queue) added to the operator set.
        # v8.18 R11-1: UC-6 (algorithm migration) added to the operator set.
        self.assertHTML(r, '>Issue a credential<')   # in the Operations group
        self.assertHTML(r, '>Migrate an algorithm<')
        self.assertHTML(r, '>Revoke<')
        self.assertHTML(r, '>Recovery<')

        self._logout()
        self._login('auditor')
        r = self.client.get('/dashboard')
        # Auditor sees SQL but not UC-1/6/8/9 (only UC-7 in the dropdown)
        self.assertHTML(r, '>SQL console<')
        self.assertNotHTML(r, '>Issue a credential<')
        self.assertNotHTML(r, '>Migrate an algorithm<')
        self.assertNotHTML(r, '>Revoke<')
        self.assertNotHTML(r, '>Recovery<')
        # Auditor still sees UC-7 in the dropdown
        self.assertHTML(r, '>Warrant audit<')


class PasswordHashingTests(unittest.TestCase):
    """Sanity checks on password hashing primitives."""

    def test_hash_password_uses_scrypt(self):
        from app import security as sec
        h = sec.hash_password('Test@1234')
        self.assertTrue(h.startswith('scrypt:'),
                        f"Expected scrypt-prefixed hash, got: {h[:30]}")

    def test_verify_password_round_trip(self):
        from app import security as sec
        h = sec.hash_password('Correct@Horse123!')
        self.assertTrue(sec.verify_password(h, 'Correct@Horse123!'))
        self.assertFalse(sec.verify_password(h, 'wrong'))

    def test_hash_uniqueness(self):
        """Two hashes of the same password should differ (salted)."""
        from app import security as sec
        h1 = sec.hash_password('SamePass@123')
        h2 = sec.hash_password('SamePass@123')
        self.assertNotEqual(h1, h2)


# ============================================================================
# V6 — CONCURRENCY HARDENING TESTS
# ============================================================================
# These tests exercise the race-condition fixes shipped in v6:
#   - Atomic increment of AppUser.failed_login_count (TOCTOU was bypassable)
#   - SELECT FOR UPDATE in uc4_activate_reserve serializes per-holder
#   - activation_sequence computed from MAX(seq)+1 inside the locked region
#
# Race tests use threading + a connection per thread. Because Postgres
# serializes via row locks rather than transaction-level optimistic
# concurrency, these tests verify correctness under concurrent load
# without depending on timing.
# ============================================================================

import threading
from concurrent.futures import ThreadPoolExecutor


class ConcurrencyTests(PolarisTestCase):
    #: How long a probe waits before Postgres calls it blocked. Generous: the only
    #: thing on the other side is a transaction this class is deliberately holding
    #: open, so a probe that waits this long waited forever.
    LOCK_TIMEOUT = '5s'

    def assertDoesNotContend(self, hold, probe, what):
        """Two operations do not share an advisory-lock key. Asked, not timed.

        `hold(cur)` runs the operation whose lock must be held. Its transaction is
        kept OPEN for the duration, so whatever `pg_advisory_xact_lock` it took is
        still held when `probe(cur)` runs. `probe` runs under `lock_timeout`, so a
        shared key raises `lock_not_available` instead of merely running slowly, and
        Postgres names the offending key expression in the error it raises.

        WHY NOT A STOPWATCH. Until v9.459 five tests in this class timed two threads
        against an estimate of the serialized cost. Every one of them was vacuous, and
        the same defect produced all five: each slept BEFORE its CALL, while the
        procedures take their advisory lock as the CALL's first statement and hold it
        to commit. So both threads always slept concurrently, and the stopwatch
        measured the sleep rather than the lock. Proven on 2026-09-14 rather than
        argued: rewriting close_anchor_batch, uc8_revoke_token, uc9_complete_recovery,
        uc6_migrate_algorithm and uc10_attest_trust with lock keys that ignore
        algorithm, agency, individual, token and attesting agency respectively left
        all five tests green.

        The estimate was unsound on its own terms too. `baseline` measured one BARE
        round trip -- connect, pg_sleep, commit -- while each worker also ran the
        procedure under test, so a genuinely serialized pair cost more than
        one baseline plus one sleep, and landed in the band v9.456 had labelled
        impossible and told you to re-run. Measured with the global-key mutant
        installed: elapsed=0.643s against a serialized estimate of 0.606s. A real
        regression would have been reported as a stalled machine.

        A lock wait has none of that. It does not move when the runner is busy, and it
        is the lock manager's own answer rather than an inference from a clock.
        """
        holding, release = threading.Event(), threading.Event()
        failures = {}

        def hold_it():
            conn = None
            try:
                conn = self._new_conn()
                with conn.cursor() as cur:
                    hold(cur)
                holding.set()          # the lock is held from here until the commit
                release.wait(timeout=30)
                conn.commit()
            except Exception as exc:   # noqa: BLE001 - reported, never swallowed
                failures['holder'] = repr(exc)
                holding.set()
            finally:
                if conn is not None:
                    conn.close()

        holder = threading.Thread(target=hold_it)
        holder.start()
        blocked = None
        try:
            self.assertTrue(holding.wait(timeout=30),
                            '%s: the holder never reached its lock' % what)
            self.assertEqual(failures, {},
                             '%s: the holder failed, so nothing held a lock' % what)
            conn = self._new_conn()
            try:
                with conn.cursor() as cur:
                    cur.execute("SET lock_timeout = %s", (self.LOCK_TIMEOUT,))
                    try:
                        probe(cur)
                        conn.commit()
                    except psycopg2.errors.LockNotAvailable as exc:
                        conn.rollback()
                        blocked = str(exc).strip()
            finally:
                conn.close()
        finally:
            release.set()
            holder.join(timeout=30)

        self.assertIsNone(
            blocked,
            '%s: the second operation waited on a lock while the first was held open, '
            'so the two share a lock key. A key that does not separate them serializes '
            'every such operation in the system behind whichever one is in flight. '
            'Postgres said: %s' % (what, blocked))
        self.assertEqual(failures, {},
                         '%s: the holder failed after taking its lock' % what)
        self.assertFalse(holder.is_alive(), '%s: the holder never let go' % what)

    #: How long a probe waits before a CONTENDS test concludes it is blocked. Short
    #: on purpose: the holder holds for the whole probe window, so a probe that is
    #: going to get through gets through in milliseconds.
    CONTENDS_TIMEOUT = '2s'

    def assertContends(self, hold, probe, what):
        """Two operations DO share an advisory-lock key, and the procedure is what
        takes it. The mirror of assertDoesNotContend, and the direction that catches a
        lock going missing rather than a key going coarse.

        THE HOLD MUST GO THROUGH THE PROCEDURE. Until v9.460 the two serialization
        tests in this class took the advisory lock BY HAND -- the test computed
        `hashtext('polaris.federation.attest.4')` itself, acquired it, slept inside the
        transaction, and then called the procedure. Both threads therefore serialized
        on the TEST's lock, and the procedure's own locking never entered the
        measurement. Proven on 2026-09-14: both procedures were reinstalled with the
        `PERFORM pg_advisory_xact_lock(...)` line deleted outright, and both tests
        passed. Between them and the five cross-entity tests, nothing in the suite
        would have noticed any of these procedures giving up its lock entirely.
        """
        holding, release = threading.Event(), threading.Event()
        failures = {}

        def hold_it():
            conn = None
            try:
                conn = self._new_conn()
                with conn.cursor() as cur:
                    hold(cur)      # the PROCEDURE takes the lock, not this test
                holding.set()
                release.wait(timeout=30)
                conn.commit()
            except Exception as exc:   # noqa: BLE001 - reported, never swallowed
                failures['holder'] = repr(exc)
                holding.set()
            finally:
                if conn is not None:
                    conn.close()

        holder = threading.Thread(target=hold_it)
        holder.start()
        blocked = passthrough = None
        try:
            self.assertTrue(holding.wait(timeout=30),
                            '%s: the holder never reached its lock' % what)
            self.assertEqual(failures, {},
                             '%s: the holder failed, so nothing held a lock' % what)
            conn = self._new_conn()
            try:
                with conn.cursor() as cur:
                    cur.execute("SET lock_timeout = %s", (self.CONTENDS_TIMEOUT,))
                    try:
                        probe(cur)
                        conn.commit()
                    except psycopg2.errors.LockNotAvailable as exc:
                        conn.rollback()
                        blocked = str(exc).strip()
                    except psycopg2.Error as exc:
                        # It reached its own logic and objected there, so it was never
                        # held at the lock. That is a passthrough, not a test error.
                        conn.rollback()
                        passthrough = str(exc).strip().splitlines()[0]
            finally:
                conn.close()
        finally:
            release.set()
            holder.join(timeout=30)

        self.assertIsNotNone(
            blocked,
            '%s: the second operation went straight through while the first was still '
            'holding its transaction open, so the procedure is not taking the advisory '
            'lock this test exists to prove it takes. The consequence is not a slow '
            'system: it is two callers inside the same critical section, which is the '
            'race the lock was added to close.%s'
            % (what, '' if passthrough is None else
               ' It got as far as its own validation and objected there: %s' % passthrough))
        self.assertEqual(failures, {},
                         '%s: the holder failed after taking its lock' % what)
        self.assertFalse(holder.is_alive(), '%s: the holder never let go' % what)

    """Tests for the v6 concurrency hardening. Run a handful of operations
    in parallel against the live database and assert the invariants hold."""

    def _new_conn(self):
        """Each thread needs its own connection — psycopg2 connections are
        not thread-safe."""
        return psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG)

    # -------------------------------------------------------------------
    # Atomic failed_login_count increment under concurrent load.
    # Pre-v6: two simultaneous failed logins both read count=N and both
    # wrote N+1, losing one failure. An attacker could spam concurrent
    # failed login attempts and never trip the lockout.
    # Post-v6: UPDATE ... SET col = col + 1 RETURNING is atomic; every
    # failure is counted exactly once.
    # -------------------------------------------------------------------
    def test_failed_login_count_is_atomic_under_concurrent_load(self):
        # Use a fresh test user so we don't interfere with the seeded admin
        with self._new_conn() as conn, conn.cursor() as cur:
            from werkzeug.security import generate_password_hash
            # v9.443: creating an account is refused without a stated reason, and this
            # fixture is a caller like any other. Same statement as the INSERT so both
            # land on this connection.
            cur.execute(
                "SELECT set_config('polaris.actor', 'test-fixture', true), "
                "       set_config('polaris.justification', "
                "                  'test fixture account for the timing and concurrency probes', true)")
            cur.execute(
                "INSERT INTO AppUser (username, password_hash, role, "
                "failed_login_count, locked_until, is_active) "
                "VALUES (%s, %s, 'auditor', 0, NULL, TRUE) "
                "ON CONFLICT (username) DO UPDATE SET "
                "  failed_login_count=0, locked_until=NULL, is_active=TRUE",
                ('concurrency_victim', generate_password_hash('CorrectPassword!1', method='scrypt'))
            )
            conn.commit()

        N_ATTEMPTS = 8
        sec = flask_app.security

        def fail_once():
            user, err = sec.authenticate(
                lambda: psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG),
                'concurrency_victim',
                'WrongPassword'
            )
            return err is not None  # True if rejected, as expected

        # Fire N parallel failed-login attempts
        with ThreadPoolExecutor(max_workers=N_ATTEMPTS) as pool:
            results = list(pool.map(lambda _: fail_once(), range(N_ATTEMPTS)))

        # All must have been rejected (None user)
        self.assertTrue(all(results),
            "All concurrent failed logins should be rejected")

        # The counter must show EXACTLY N_ATTEMPTS — no lost increments.
        # Pre-v6 this would frequently land at N-1 or N-2 due to TOCTOU.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute(
                "SELECT failed_login_count, locked_until FROM AppUser "
                "WHERE username = %s",
                ('concurrency_victim',))
            row = cur.fetchone()
            self.assertEqual(row['failed_login_count'], N_ATTEMPTS,
                f"Atomic increment lost updates: expected {N_ATTEMPTS}, "
                f"got {row['failed_login_count']}")
            # Account should be locked since N_ATTEMPTS (8) > threshold (5)
            self.assertIsNotNone(row['locked_until'],
                "Account should be locked after threshold-crossing failures")

        # Cleanup
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("DELETE FROM AuthAuditLog WHERE username = 'concurrency_victim'")
            cur.execute("DELETE FROM AppUser WHERE username = 'concurrency_victim'")
            conn.commit()

    # -------------------------------------------------------------------
    # The partial unique index uq_one_active_per_person enforces at most
    # one ACTIVE token per individual at the database level. Two parallel
    # attempts to set status='ACTIVE' for the same individual must
    # serialize: exactly one succeeds, others get UniqueViolation.
    # -------------------------------------------------------------------
    def test_partial_unique_index_blocks_double_active(self):
        with self._new_conn() as conn, conn.cursor() as cur:
            # Find an individual who has two RESERVE tokens we can race for ACTIVE
            cur.execute("""
                SELECT individual_id, array_agg(token_id) AS tokens
                FROM IdentityToken
                WHERE status = 'RESERVE'
                GROUP BY individual_id
                HAVING count(*) >= 2
                LIMIT 1
            """)
            row = cur.fetchone()
            # If the sample set doesn't naturally contain two RESERVE tokens
            # for the same individual, create them.
            if not row:
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES ('Race Test Subject', '1990-01-01', 'US')
                    RETURNING individual_id
                """)
                ind_id = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO IdentityToken
                        (token_value, physical_serial, biometric_binding_type,
                         individual_id, issuing_agency_id, algorithm_id, status)
                    VALUES
                        ('RACE-A', 'HW-RACE-A', 'NONE', %s, 1, 1, 'RESERVE'),
                        ('RACE-B', 'HW-RACE-B', 'NONE', %s, 1, 1, 'RESERVE')
                    RETURNING token_id
                """, (ind_id, ind_id))
                cur.execute("SELECT token_id FROM IdentityToken WHERE individual_id=%s",
                    (ind_id,))
                tokens = [r['token_id'] for r in cur.fetchall()]
                conn.commit()
            else:
                tokens = row['tokens'][:2]

        results = {'success': 0, 'unique_violation': 0, 'other_error': 0}
        results_lock = threading.Lock()

        def race_activate(token_id):
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute(
                        "UPDATE IdentityToken SET status='ACTIVE', "
                        "activated_date=CURRENT_TIMESTAMP WHERE token_id=%s",
                        (token_id,))
                    conn.commit()
                with results_lock: results['success'] += 1
            except psycopg2.errors.UniqueViolation:
                with results_lock: results['unique_violation'] += 1
            except psycopg2.Error:
                with results_lock: results['other_error'] += 1

        threads = [threading.Thread(target=race_activate, args=(t,)) for t in tokens]
        for t in threads: t.start()
        for t in threads: t.join()

        # Exactly one must succeed; the other gets UniqueViolation
        self.assertEqual(results['success'], 1,
            f"Exactly one parallel activation should succeed: {results}")
        self.assertEqual(results['unique_violation'], 1,
            f"The losing thread should get UniqueViolation: {results}")

    def test_uc4_concurrent_same_tokens_one_winner_no_duplicate_crl(self):
        """Two concurrent uc4_activate_reserve calls on the SAME lost+reserve
        tokens must not both succeed. The procedure re-validates the token
        statuses under its per-holder lock (not on the stale pre-lock read), so
        the loser sees the post-commit LOST status and fails cleanly, leaving
        exactly one RevocationList row for the lost token rather than a duplicate
        CRL publication. This exercises the PROCEDURE concurrently — the older
        test above races raw UPDATEs and never calls uc4."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('UC4 Race Holder', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            ind_id = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, biometric_binding_type,
                     individual_id, issuing_agency_id, algorithm_id, status,
                     activated_date)
                VALUES ('UC4RACE-ACT', 'SN-UC4RACE-ACT', 'NONE', %s, 1, 1,
                        'ACTIVE', CURRENT_TIMESTAMP)
                RETURNING token_id
            """, (ind_id,))
            active_id = cur.fetchone()['token_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, biometric_binding_type,
                     individual_id, issuing_agency_id, algorithm_id, status)
                VALUES ('UC4RACE-RES', 'SN-UC4RACE-RES', 'NONE', %s, 1, 1, 'RESERVE')
                RETURNING token_id
            """, (ind_id,))
            reserve_id = cur.fetchone()['token_id']
            conn.commit()

        results = {'success': 0, 'rejected_not_active': 0, 'other': 0}
        results_lock = threading.Lock()

        def race(suffix):
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute(
                        "SELECT uc4_activate_reserve(%s, 3, 'LOST', %s, %s)",
                        (active_id, reserve_id,
                         f'https://crl.idtoken.gov/uc4race/{suffix}'))
                    conn.commit()
                with results_lock: results['success'] += 1
            except psycopg2.Error as e:
                with results_lock:
                    if 'not ACTIVE' in str(e):
                        results['rejected_not_active'] += 1
                    else:
                        results['other'] += 1

        threads = [threading.Thread(target=race, args=(i,)) for i in range(2)]
        for t in threads: t.start()
        for t in threads: t.join()

        self.assertEqual(results['success'], 1,
            f"exactly one concurrent uc4 should win: {results}")
        self.assertEqual(results['rejected_not_active'], 1,
            f"the loser must fail cleanly with 'not ACTIVE', not corrupt state: {results}")

        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS c FROM RevocationList WHERE token_id=%s",
                        (active_id,))
            self.assertEqual(cur.fetchone()['c'], 1,
                'the lost token must be on the RevocationList exactly once (no duplicate)')

    def test_uc4_reserve_recheck_under_lock_refuses_a_reserve_moved_meanwhile(self):
        """uc4 reads the reserve as RESERVE, then waits for the holder's row lock; while it
        waits, another transaction revokes the reserve and commits. The re-check under the
        lock must refuse with 'not in RESERVE state'. The interleaving is forced, not raced:
        the test holds the lock itself and releases it only once uc4 is seen waiting on it,
        so the pre-lock copy of the check has already passed and only the under-lock copy
        can catch it. The reserve is revoked through uc8, the only sanctioned path,
        with a co-signer so the issuer's revocation bound cannot refuse it first.
        Before 2026-09-23 no test drove this and the procedure mutation drill
        recorded the under-lock check as a survivor."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('UC4 Recheck Holder', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            ind_id = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, biometric_binding_type,
                     individual_id, issuing_agency_id, algorithm_id, status,
                     activated_date)
                VALUES ('UC4RECHK-ACT', 'SN-UC4RECHK-ACT', 'NONE', %s, 2, 1,
                        'ACTIVE', CURRENT_TIMESTAMP)
                RETURNING token_id
            """, (ind_id,))
            active_id = cur.fetchone()['token_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, biometric_binding_type,
                     individual_id, issuing_agency_id, algorithm_id, status)
                VALUES ('UC4RECHK-RES', 'SN-UC4RECHK-RES', 'NONE', %s, 2, 1, 'RESERVE')
                RETURNING token_id
            """, (ind_id,))
            reserve_id = cur.fetchone()['token_id']
            conn.commit()

        holder = self._new_conn()
        caller = self._new_conn()
        outcome = {}
        try:
            with holder.cursor() as hcur:
                hcur.execute("SELECT 1 FROM Individual WHERE individual_id=%s FOR UPDATE",
                             (ind_id,))
            caller_pid = caller.get_backend_pid()

            def call_uc4():
                try:
                    with caller.cursor() as ccur:
                        ccur.execute(
                            "SELECT uc4_activate_reserve(%s, 3, 'LOST', %s, %s)",
                            (active_id, reserve_id,
                             'https://crl.idtoken.gov/uc4recheck/1'))
                    caller.commit()
                    outcome['ok'] = True
                except psycopg2.Error as e:
                    caller.rollback()
                    outcome['error'] = str(e)

            t = threading.Thread(target=call_uc4)
            t.start()
            waiting = False
            with self._new_conn() as probe, probe.cursor() as pcur:
                for _ in range(200):
                    pcur.execute("SELECT wait_event_type FROM pg_stat_activity WHERE pid=%s",
                                 (caller_pid,))
                    row = pcur.fetchone()
                    probe.rollback()
                    if row and row['wait_event_type'] == 'Lock':
                        waiting = True
                        break
                    _rl_time.sleep(0.025)
            self.assertTrue(waiting, 'uc4 never blocked on the holder lock; the '
                                     'interleaving this test forces did not happen')

            with holder.cursor() as hcur:
                hcur.execute("CALL uc8_revoke_token(%s, 2, 'ADMINISTRATIVE', %s, 1)",
                             (reserve_id, 'https://crl.idtoken.gov/uc4recheck/reserve'))
            holder.commit()
            t.join(timeout=30)
            self.assertFalse(t.is_alive(), 'uc4 did not return after the lock was released')
        finally:
            holder.close()
            caller.close()

        self.assertNotIn('ok', outcome, 'uc4 activated a reserve that was revoked while '
                                        'it waited for the lock')
        self.assertIn('not in RESERVE state', outcome.get('error', ''),
                      f'the under-lock re-check must be what refuses: {outcome}')
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT status FROM IdentityToken WHERE token_id=%s", (active_id,))
            self.assertEqual(cur.fetchone()['status'], 'ACTIVE',
                             "the holder's credential must be left ACTIVE by the refusal")

    # -------------------------------------------------------------------
    # R11-6 / M2-11 — pg_advisory_xact_lock prevents two concurrent
    # boundary-tripping revocations from both succeeding. Each thread
    # has its own connection; the procedure serializes them by agency_id.
    # -------------------------------------------------------------------
    def test_uc8_advisory_lock_prevents_double_revoke_at_boundary(self):
        # Seed: agency 2 gets a 50% override + two fresh ACTIVE tokens
        # under it. After one revocation that single agency is past the
        # bound (1/2 = 50% which is == not >; bumping to 49% so the
        # SECOND revoke must be rejected). The first thread to acquire
        # the advisory lock will be UNDER the bound; the second will
        # find itself OVER and require a co-signer (which it doesn't
        # provide here).
        with self._new_conn() as conn, conn.cursor() as cur:
            set_discretion_bound(cur, 2, 49.00,
                                 why='C9 concurrency test fixture for boundary-race')
            conn.commit()

        def seed_active(label):
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES (%s, '1990-01-01', 'US-PA')
                    RETURNING individual_id
                """, (f'R11-6 C9 {label}',))
                iid = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO IdentityToken
                        (token_value, physical_serial, hardware_model,
                         biometric_binding_type, individual_id, issuing_agency_id,
                         algorithm_id, status, issued_date, expiration_date)
                    VALUES
                        (%s, %s, 'TitanQ-3', 'IRIS', %s, 2, 1,
                         'RESERVE', CURRENT_TIMESTAMP,
                         (polaris_utc_date() + INTERVAL '10 years')::date)
                    RETURNING token_id
                """, (f'TKN-R11-6-C9-{label}', f'SN-R11-6-C9-{label}', iid))
                tid = cur.fetchone()['token_id']
                cur.execute("SELECT set_config('polaris.actor_agency_id', '2', false)")
                cur.execute("SELECT set_config('polaris.reason_code', 'TEST_SEED', false)")
                cur.execute("UPDATE IdentityToken SET status='ACTIVE', activated_date=CURRENT_TIMESTAMP WHERE token_id=%s", (tid,))
                conn.commit()
            return tid

        # Create two tokens. The denominator (agency 2's outstanding count)
        # includes any existing tokens — the bound math handles this.
        tids = [seed_active(f'race-{i}') for i in range(2)]

        results = {'success': 0, 'rejected_co_sign_required': 0, 'other_error': 0}
        results_lock = threading.Lock()

        def race_revoke(token_id):
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute(
                        "CALL uc8_revoke_token(%s, %s, %s, %s, %s)",
                        (token_id, 2, 'ADMINISTRATIVE',
                         'https://crl.idtoken.gov/test/C9.crl', None))
                    conn.commit()
                with results_lock: results['success'] += 1
            except psycopg2.errors.CheckViolation:
                with results_lock: results['rejected_co_sign_required'] += 1
            except psycopg2.Error as e:
                with results_lock:
                    results['other_error'] += 1
                    results.setdefault('other_msgs', []).append(str(e))

        threads = [threading.Thread(target=race_revoke, args=(t,)) for t in tids]
        for t in threads: t.start()
        for t in threads: t.join()

        # Exactly one of the two must succeed (the bound permits one).
        # The losing thread sees the post-commit count and gets the
        # 'co-signer required' check_violation.
        self.assertEqual(results['success'], 1,
            f"Advisory-lock contract: exactly one thread should succeed at the boundary: {results}")
        self.assertEqual(results['rejected_co_sign_required'], 1,
            f"The losing thread should be rejected with co-signer required: {results}")

    # -------------------------------------------------------------------
    # R11-6 / M2-11 — Cross-agency revocations don't block each other.
    # The advisory-lock key is hashtext('polaris.revoke.' || agency_id),
    # so two different agencies revoking simultaneously do not serialize.
    # -------------------------------------------------------------------
    def test_uc8_cross_agency_revocations_do_not_block(self):
        # Permissive overrides for both agency 2 and agency 3.
        with self._new_conn() as conn, conn.cursor() as cur:
            set_discretion_bound(cur, (2, 3), 95.00,
                                 why='C9 cross-agency test: permissive for both agencies')
            conn.commit()

        def seed_active(agency_id, label):
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES (%s, '1990-01-01', 'US-PA')
                    RETURNING individual_id
                """, (f'R11-6 CROSS {label}',))
                iid = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO IdentityToken
                        (token_value, physical_serial, hardware_model,
                         biometric_binding_type, individual_id, issuing_agency_id,
                         algorithm_id, status, issued_date, expiration_date)
                    VALUES
                        (%s, %s, 'TitanQ-3', 'IRIS', %s, %s, 1,
                         'RESERVE', CURRENT_TIMESTAMP,
                         (polaris_utc_date() + INTERVAL '10 years')::date)
                    RETURNING token_id
                """, (f'TKN-R11-6-CROSS-{label}', f'SN-R11-6-CROSS-{label}', iid, agency_id))
                tid = cur.fetchone()['token_id']
                cur.execute("SELECT set_config('polaris.actor_agency_id', %s, false)", (str(agency_id),))
                cur.execute("SELECT set_config('polaris.reason_code', 'TEST_SEED', false)")
                cur.execute("UPDATE IdentityToken SET status='ACTIVE', activated_date=CURRENT_TIMESTAMP WHERE token_id=%s", (tid,))
                conn.commit()
            return tid

        tid_a = seed_active(2, 'a')
        tid_b = seed_active(3, 'b')

        def revoke(agency_id, token_id):
            return lambda cur: cur.execute(
                "CALL uc8_revoke_token(%s, %s, %s, %s, %s)",
                (token_id, agency_id, 'ADMINISTRATIVE',
                 'https://crl.idtoken.gov/test/cross.crl', None))

        self.assertDoesNotContend(revoke(2, tid_a), revoke(3, tid_b),
                                  'Cross-agency revocations')

        # Both landed. The helper proves they did not wait on each other; this proves
        # they happened, which a lock test that never checks its own effect does not.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT token_id, status FROM IdentityToken "
                        "WHERE token_id IN (%s, %s) ORDER BY token_id", (tid_a, tid_b))
            states = {r['token_id']: r['status'] for r in cur.fetchall()}
        self.assertEqual(states, {tid_a: 'REVOKED', tid_b: 'REVOKED'},
                         'both cross-agency revocations should have taken effect')

    # -------------------------------------------------------------------
    # R11-2 / M2-7 — pg_advisory_xact_lock on claimed_individual_id
    # prevents two threads from both completing the same PENDING recovery.
    # -------------------------------------------------------------------
    def test_uc9_advisory_lock_serializes_concurrent_completes(self):
        """Race uc9_complete_recovery on the same PENDING with T threads.
        Exactly one should succeed; the others should fail with
        'not PENDING' because the winner committed first."""
        # Seed: fresh Individual + PENDING with channels verified + cool-down past.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('R11-2 C9 race', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            iid = cur.fetchone()['individual_id']

            cur.execute("SELECT user_id FROM AppUser WHERE username='operator'")
            op_uid = cur.fetchone()['user_id']
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin_uid = cur.fetchone()['user_id']
            cur.execute("SELECT user_id FROM AppUser WHERE username='auditor'")
            auditor_uid = cur.fetchone()['user_id']

            cur.execute("""
                INSERT INTO RecoveryRequest
                    (claimed_individual_id, requested_at, requesting_agency_id,
                     requesting_user_id, biometric_verified, sworn_statement_hash,
                     witness_agency_id, witness_co_sign_user_id,
                     cooldown_expires_at)
                VALUES (
                    %s,
                    CURRENT_TIMESTAMP - INTERVAL '50 hours',
                    1, %s, TRUE, %s, 3, %s,
                    CURRENT_TIMESTAMP - INTERVAL '2 hours'
                )
                RETURNING recovery_id
            """, (iid, op_uid, 'a' * 64, auditor_uid))
            rid = cur.fetchone()['recovery_id']
            conn.commit()

        N = 4
        results = {'success': 0, 'rejected_not_pending': 0, 'other': 0}
        results_lock = threading.Lock()

        def race_complete(suffix):
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute("""
                        CALL uc9_complete_recovery(%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """, (
                        rid, admin_uid, 'APPROVED', f'race {suffix}',
                        f'TKN-UC9-RACE-{suffix}', f'SN-UC9-RACE-{suffix}',
                        1, 'IRIS', 'MULTI_MODAL',
                        f'https://crl.idtoken.gov/race/{suffix}',
                        *_recovery_signature(f'TKN-UC9-RACE-{suffix}'),
                    ))
                    conn.commit()
                with results_lock: results['success'] += 1
            except psycopg2.Error as e:
                msg = str(e)
                with results_lock:
                    if 'not PENDING' in msg or 'already in status' in msg:
                        results['rejected_not_pending'] += 1
                    else:
                        results['other'] += 1
                        results.setdefault('other_msgs', []).append(msg)

        threads = [threading.Thread(target=race_complete, args=(i,)) for i in range(N)]
        for t in threads: t.start()
        for t in threads: t.join()

        self.assertEqual(results['success'], 1,
            f"Advisory-lock contract: exactly one thread should complete the PENDING: {results}")
        self.assertEqual(results['rejected_not_pending'], N - 1,
            f"The losing threads should see 'not PENDING' after the winner committed: {results}")

    # -------------------------------------------------------------------
    # R11-2 / M2-7 — Cross-individual recoveries do not block each other.
    # -------------------------------------------------------------------
    def test_uc9_cross_individual_recoveries_do_not_block(self):
        """Two PENDING recoveries for two different individuals should
        complete in parallel — the advisory-lock key is per-individual."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='operator'")
            op_uid = cur.fetchone()['user_id']
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin_uid = cur.fetchone()['user_id']
            cur.execute("SELECT user_id FROM AppUser WHERE username='auditor'")
            auditor_uid = cur.fetchone()['user_id']

            def make_pending(label):
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES (%s, '1990-01-01', 'US-PA')
                    RETURNING individual_id
                """, (f'R11-2 CROSS {label}',))
                iid = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO RecoveryRequest
                        (claimed_individual_id, requested_at, requesting_agency_id,
                         requesting_user_id, biometric_verified, sworn_statement_hash,
                         witness_agency_id, witness_co_sign_user_id,
                         cooldown_expires_at)
                    VALUES (
                        %s,
                        CURRENT_TIMESTAMP - INTERVAL '50 hours',
                        1, %s, TRUE, %s, 3, %s,
                        CURRENT_TIMESTAMP - INTERVAL '2 hours'
                    )
                    RETURNING recovery_id
                """, (iid, op_uid, 'a' * 64, auditor_uid))
                return cur.fetchone()['recovery_id']

            rid_a = make_pending('A')
            rid_b = make_pending('B')
            conn.commit()

        def complete(rid, suffix):
            return lambda cur: cur.execute("""
                CALL uc9_complete_recovery(%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                rid, admin_uid, 'APPROVED', f'cross {suffix}',
                f'TKN-UC9-XR-{suffix}', f'SN-UC9-XR-{suffix}',
                1, 'IRIS', 'MULTI_MODAL',
                f'https://crl.idtoken.gov/xr/{suffix}',
                *_recovery_signature(f'TKN-UC9-XR-{suffix}'),
            ))

        self.assertDoesNotContend(complete(rid_a, 'A'), complete(rid_b, 'B'),
                                  'Cross-individual recoveries')

        # Both landed. The helper proves they did not wait on each other; this proves
        # they happened, which a lock test that never checks its own effect does not.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT recovery_id, status, resulting_token_id IS NOT NULL AS issued
                  FROM RecoveryRequest WHERE recovery_id IN (%s, %s)
            """, (rid_a, rid_b))
            landed = {r['recovery_id']: (r['status'], r['issued'])
                      for r in cur.fetchall()}
        self.assertEqual(landed, {rid_a: ('APPROVED', True), rid_b: ('APPROVED', True)},
                         'both cross-individual recoveries should have taken effect')

    # -------------------------------------------------------------------
    # R11-1 / M2-6 — pg_advisory_xact_lock on token_id serializes
    # concurrent uc6_migrate_algorithm calls on the same token.
    # -------------------------------------------------------------------
    def test_uc6_per_token_lock_serializes_concurrent_migrations(self):
        """T threads each migrate the same token to T distinct algorithms.
        Lock serializes them; final state has 1 (original) + T new
        signatures, all under different algorithms. The UNIQUE
        (token_id, algorithm_id) constraint prevents duplicate-algorithm
        inserts; the lock prevents interleaved trigger checks."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('R11-1 C9 per-token', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            iid = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, hardware_model,
                     biometric_binding_type, individual_id, issuing_agency_id,
                     algorithm_id, status, issued_date, expiration_date)
                VALUES ('TKN-R11-1-LOCK', 'SN-R11-1-LOCK', 'TitanQ-3',
                        'IRIS', %s, 1, 1, 'RESERVE',
                        CURRENT_TIMESTAMP, (polaris_utc_date() + INTERVAL '10 years')::date)
                RETURNING token_id
            """, (iid,))
            tid = cur.fetchone()['token_id']
            cur.execute("""
                INSERT INTO TokenSignature (token_id, algorithm_id, signature_bytes)
                VALUES (%s, 1, %s)
            """, (tid, b'TEST_LOCK_SEED'))
            conn.commit()

        # Use 3 distinct algorithm_ids for the migrations: 2, 3, 4.
        # (Algorithm 1 is already on the token; algorithm 5 is deprecated.)
        target_algs = [2, 3, 4]
        results = []
        results_lock = threading.Lock()

        def migrate(alg_id):
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute(
                        "CALL uc6_migrate_algorithm(%s, %s, %s, %s)",
                        (tid, alg_id, f'MIG_{alg_id}'.encode(), False))
                    conn.commit()
                with results_lock: results.append(('ok', alg_id))
            except psycopg2.Error as e:
                with results_lock: results.append(('err', alg_id, str(e)))

        threads = [threading.Thread(target=migrate, args=(a,)) for a in target_algs]
        for t in threads: t.start()
        for t in threads: t.join()

        successes = [r for r in results if r[0] == 'ok']
        self.assertEqual(len(successes), 3,
            f"All 3 distinct-algorithm migrations should succeed: {results}")

        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT count(*) AS c FROM TokenSignature WHERE token_id=%s
            """, (tid,))
            self.assertEqual(cur.fetchone()['c'], 4,
                'Final state: 1 seed + 3 migrations = 4 signatures')

    def test_uc6_verification_snapshot_consistent_with_migration(self):
        """Verify-then-migrate consistency model: within a transaction's
        read snapshot, the active-signature set is stable even if a
        concurrent migration commits in the middle. New migrations are
        visible only to subsequent transactions. This documents the
        consistency contract — a verification path can trust its
        snapshot reads."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('R11-1 verify-migrate', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            iid = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, hardware_model,
                     biometric_binding_type, individual_id, issuing_agency_id,
                     algorithm_id, status, issued_date, expiration_date)
                VALUES ('TKN-R11-1-SNAP', 'SN-R11-1-SNAP', 'TitanQ-3',
                        'IRIS', %s, 1, 1, 'RESERVE',
                        CURRENT_TIMESTAMP, (polaris_utc_date() + INTERVAL '10 years')::date)
                RETURNING token_id
            """, (iid,))
            tid = cur.fetchone()['token_id']
            cur.execute("""
                INSERT INTO TokenSignature (token_id, algorithm_id, signature_bytes)
                VALUES (%s, 1, %s)
            """, (tid, b'SNAP_SEED'))
            conn.commit()

        # Verifier-thread: open a transaction with REPEATABLE READ
        # isolation and observe the active-signature set. Then sleep,
        # then re-read. The set should be identical even though the
        # migrator commits during the sleep.
        verifier_snapshot = []
        migrator_done = threading.Event()

        def verifier():
            conn = self._new_conn()
            try:
                conn.set_isolation_level(psycopg2.extensions.ISOLATION_LEVEL_REPEATABLE_READ)
                with conn.cursor() as cur:
                    cur.execute("""
                        SELECT algorithm_id FROM TokenSignature
                        WHERE token_id=%s AND deprecation_date IS NULL
                        ORDER BY algorithm_id
                    """, (tid,))
                    verifier_snapshot.append(
                        ('pre', tuple(r['algorithm_id'] for r in cur.fetchall())))
                    # Wait for migrator to commit.
                    migrator_done.wait(timeout=5)
                    cur.execute("""
                        SELECT algorithm_id FROM TokenSignature
                        WHERE token_id=%s AND deprecation_date IS NULL
                        ORDER BY algorithm_id
                    """, (tid,))
                    verifier_snapshot.append(
                        ('post', tuple(r['algorithm_id'] for r in cur.fetchall())))
                conn.commit()
            finally:
                conn.close()

        def migrator():
            # Brief sleep so the verifier opens its snapshot first.
            import time as _t; _t.sleep(0.1)
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("CALL uc6_migrate_algorithm(%s, %s, %s, %s)",
                            (tid, 2, b'SNAP_MIG', False))
                conn.commit()
            migrator_done.set()

        v_thread = threading.Thread(target=verifier)
        m_thread = threading.Thread(target=migrator)
        v_thread.start(); m_thread.start()
        v_thread.join(); m_thread.join()

        # The verifier saw the same set both times (snapshot isolation).
        self.assertEqual(verifier_snapshot[0][1], verifier_snapshot[1][1],
            f"Verifier's REPEATABLE READ snapshot should be stable: {verifier_snapshot}")
        # And the verifier's set was {1} — the seed signature only, not
        # the {1, 2} the migrator added.
        self.assertEqual(verifier_snapshot[0][1], (1,),
            f"Verifier should see only the pre-migration signature: {verifier_snapshot}")

        # After both transactions complete, a fresh read sees the new sig.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT algorithm_id FROM TokenSignature
                WHERE token_id=%s AND deprecation_date IS NULL
                ORDER BY algorithm_id
            """, (tid,))
            post = tuple(r['algorithm_id'] for r in cur.fetchall())
        self.assertEqual(post, (1, 2),
            'A fresh transaction sees the migrator-added signature')

    def test_uc6_cross_token_migrations_run_in_parallel(self):
        """Two threads migrating two different tokens should complete
        in parallel — the advisory-lock key is per-token."""
        def seed():
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES ('R11-1 xtoken', '1990-01-01', 'US-PA')
                    RETURNING individual_id
                """)
                iid = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO IdentityToken
                        (token_value, physical_serial, hardware_model,
                         biometric_binding_type, individual_id, issuing_agency_id,
                         algorithm_id, status, issued_date, expiration_date)
                    VALUES (%s, %s, 'TitanQ-3', 'IRIS', %s, 1, 1,
                            'RESERVE', CURRENT_TIMESTAMP,
                            (polaris_utc_date() + INTERVAL '10 years')::date)
                    RETURNING token_id
                """, (f'TKN-R11-1-X{iid}', f'SN-R11-1-X{iid}', iid))
                tid = cur.fetchone()['token_id']
                cur.execute("""
                    INSERT INTO TokenSignature (token_id, algorithm_id, signature_bytes)
                    VALUES (%s, 1, %s)
                """, (tid, f'XSEED_{tid}'.encode()))
                conn.commit()
            return tid

        tid_a = seed()
        tid_b = seed()

        def migrate(token_id, label):
            return lambda cur: cur.execute(
                "CALL uc6_migrate_algorithm(%s, %s, %s, %s)",
                (token_id, 2, f'XMIG_{label}'.encode(), False))

        self.assertDoesNotContend(migrate(tid_a, 'A'), migrate(tid_b, 'B'),
                                  'Cross-token migrations')

        # Both migrations landed: each token carries its algorithm-2 signature.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT token_id FROM TokenSignature
                 WHERE token_id IN (%s, %s) AND algorithm_id = 2
            """, (tid_a, tid_b))
            migrated = {r['token_id'] for r in cur.fetchall()}
        self.assertEqual(migrated, {tid_a, tid_b},
                         'both cross-token migrations should have taken effect')

    # -------------------------------------------------------------------
    # R10-2 / M2-2 — Per-algorithm advisory-lock on close_anchor_batch.
    # The lock key is hashtext('polaris.anchor.close-batch.' || alg_id),
    # so same-algorithm batch-closes serialize and cross-algorithm
    # batch-closes parallelize. The serialization protects against the
    # phantom-batch race: two parallel close_anchor_batch calls for the
    # same algorithm would otherwise see overlapping pending leaf sets
    # and produce two batches with the same root or split leaves
    # silently between two roots — either way, broken audit-of-record.
    # -------------------------------------------------------------------
    def test_close_anchor_batch_same_algorithm_serializes(self):
        from anchoring import compute_batch
        from psycopg2.extras import Json

        # Seed two fresh pending anchors under algorithm 2 (ML-DSA-87).
        # We'll let close_anchor_batch sweep them; if the lock fails,
        # both threads run concurrently, each thread sees both rows as
        # pending, and we get two batches with batch_size=2 — total 4.
        with self._new_conn() as conn, conn.cursor() as cur:
            for i in range(2):
                cur.execute("""
                    INSERT INTO BlockchainAnchor
                        (token_id, did, commitment_hash, ledger_network,
                         anchor_tx_hash, anchored_date)
                    VALUES (3, %s, %s, 'ALGORAND_PQ', %s, CURRENT_TIMESTAMP)
                """, (f'did:polaris:test:race{i}',
                      f'0xc0ffee0{i}',
                      f'0xrace{i}tx'))
            conn.commit()

        def race_close():
            try:
                with self._new_conn() as conn, conn.cursor() as cur:
                    cur.execute("""
                        SELECT a.anchor_id, a.commitment_hash
                          FROM BlockchainAnchor a
                          JOIN IdentityToken t ON a.token_id = t.token_id
                         WHERE a.batch_id IS NULL AND t.algorithm_id = 2
                         ORDER BY a.anchor_id
                    """)
                    leaves = [(int(r['anchor_id']), r['commitment_hash'])
                              for r in cur.fetchall()]
                    if not leaves:
                        return 'EMPTY'
                    root, proofs = compute_batch(leaves)
                    cur.execute("CALL close_anchor_batch(%s, %s, %s)",
                                (2, root, Json(proofs)))
                    conn.commit()
                    return 'OK'
            except psycopg2.errors.NoDataFound:
                return 'EMPTY'

        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=2) as pool:
            results = list(pool.map(lambda _: race_close(), range(2)))

        # One thread closes the batch; the other finds no pending and
        # raises no_data_found (caught above and returned 'EMPTY').
        # The advisory lock guarantees ordering — no double-count.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT batch_size FROM AnchorBatch
                 WHERE algorithm_id = 2 ORDER BY batch_id DESC LIMIT 1
            """)
            last = cur.fetchone()
            self.assertEqual(last['batch_size'], 2,
                f'Same-algorithm parallel closes must coalesce into one '
                f'batch of size 2, not split. Results: {results}')

    # -------------------------------------------------------------------
    # R10-2 / M2-2 — Cross-algorithm batch-closes don't serialize.
    # Different algorithm_id → different advisory-lock key → parallel.
    # -------------------------------------------------------------------
    def test_close_anchor_batch_cross_algorithm_parallel(self):
        """Two closes under different algorithms must not wait on each other.

        NOT A STOPWATCH, AND IT USED TO BE ONE. Until v9.459 this measured wall
        clock: each thread slept 0.3s and the pair had to finish under 0.55s.
        Two things were wrong with that. The sleep came BEFORE the CALL, and
        close_anchor_batch takes its advisory lock as the CALL's first statement
        and holds it to commit, so both threads slept concurrently whether or
        not their keys collided. Rewriting the procedure with a constant lock
        key that ignores the algorithm entirely left this test green. And the
        0.55s line was 9% away from the value a healthy run produced, so it went
        red on a loaded CI runner for reasons that had nothing to do with locks.

        What it does instead: one worker calls the procedure for algorithm 2 and
        holds its transaction open, so algorithm 2's lock is held for as long as
        this test wants. The main thread then closes algorithm 3 under a
        lock_timeout. A distinct key returns at once; a shared key waits for a
        commit that has not happened yet and raises. No threshold, and the
        answer does not move when the machine is busy.
        """
        from anchoring import compute_batch
        from psycopg2.extras import Json

        # Seed pending anchors under two algorithms (2 and 3). Use the
        # existing test tokens 3 (alg=2) and 4 (alg=3).
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO BlockchainAnchor
                    (token_id, did, commitment_hash, ledger_network,
                     anchor_tx_hash, anchored_date)
                VALUES (3, 'did:polaris:test:xalg-2', '0xdec0de02',
                        'ALGORAND_PQ', '0xxalg2tx', CURRENT_TIMESTAMP),
                       (4, 'did:polaris:test:xalg-3', '0xdec0de03',
                        'ALGORAND_PQ', '0xxalg3tx', CURRENT_TIMESTAMP)
            """)
            conn.commit()

        def batch_args(alg_id):
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("""
                    SELECT a.anchor_id, a.commitment_hash
                      FROM BlockchainAnchor a
                      JOIN IdentityToken t ON a.token_id = t.token_id
                     WHERE a.batch_id IS NULL AND t.algorithm_id = %s
                     ORDER BY a.anchor_id
                """, (alg_id,))
                leaves = [(int(r['anchor_id']), r['commitment_hash'])
                          for r in cur.fetchall()]
            self.assertTrue(leaves, f'nothing pending under algorithm {alg_id}')
            root, proofs = compute_batch(leaves)
            return (alg_id, root, Json(proofs))

        alg2, alg3 = batch_args(2), batch_args(3)

        def close(args):
            return lambda cur: cur.execute(
                "CALL close_anchor_batch(%s, %s, %s)", args)

        self.assertDoesNotContend(close(alg2), close(alg3),
                                  'Cross-algorithm batch closes')

        # Both landed. The helper proves they did not wait on each other; this proves
        # they happened, which a lock test that never checks its own effect does not.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT algorithm_id FROM AnchorBatch
                 WHERE algorithm_id IN (2, 3)
                   AND created_at > CURRENT_TIMESTAMP - INTERVAL '2 minutes'
            """)
            closed = {r['algorithm_id'] for r in cur.fetchall()}
        self.assertEqual(closed, {2, 3},
                         'both cross-algorithm batch closes should have taken effect')

    # -------------------------------------------------------------------
    # R11-3 / M2-8 — Per-attesting-agency advisory-lock on
    # uc10_attest_trust / uc10_revoke_attestation. Same-attesting-agency
    # attest + concurrent revoke serialize; cross-attesting-agency
    # operations parallelize.
    # -------------------------------------------------------------------
    def test_uc10_same_attesting_agency_serializes(self):
        """Two uc10_attest_trust calls under the same attesting agency serialize.

        The docstring this replaces described the defect: "each thread manually
        acquires the lock first, then sleeps INSIDE the transaction". Acquiring it
        by hand means both threads serialize on the TEST's lock and the procedure's
        own locking never enters the measurement. Reinstalling uc10_attest_trust
        with its pg_advisory_xact_lock line deleted left that version green.
        """
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin = cur.fetchone()['user_id']
            cur.execute("SELECT context_id FROM VerificationContext WHERE context_type='VOTING'")
            ctx_voting = cur.fetchone()['context_id']
            cur.execute("SELECT context_id FROM VerificationContext WHERE context_type='MOTOR_VEHICLE'")
            ctx_mv = cur.fetchone()['context_id']

        # Both calls use attesting=4 (TSA), so the procedure computes the same key
        # for each. Two different contexts, so nothing but the lock separates them.
        def attest(context_id):
            return lambda cur: cur.execute(
                "CALL uc10_attest_trust(%s, %s, %s, %s, %s)",
                (4, 1, context_id,
                 (datetime.now(timezone.utc).date() + timedelta(days=180)), admin))

        self.assertContends(attest(ctx_voting), attest(ctx_mv),
                            'Same-attesting-agency attests')

    def test_uc10_cross_attesting_agency_parallelizes(self):
        """uc10_attest_trust calls from different attesting agencies hold
        different advisory locks and run in parallel."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin = cur.fetchone()['user_id']
            cur.execute("SELECT context_id FROM VerificationContext WHERE context_type='MOTOR_VEHICLE'")
            ctx_mv = cur.fetchone()['context_id']

        def attest(attesting_id):
            # attesting=4 and attesting=5 both attest to agency 2 in MV, so the
            # attesting agency is the only thing separating their lock keys.
            return lambda cur: cur.execute(
                "CALL uc10_attest_trust(%s, %s, %s, %s, %s)",
                (attesting_id, 2, ctx_mv,
                 (datetime.now(timezone.utc).date() + timedelta(days=180)), admin))

        self.assertDoesNotContend(attest(4), attest(5),
                                  'Cross-attesting-agency attests')

        # Both landed. The helper proves they did not wait on each other; this proves
        # they happened, which a lock test that never checks its own effect does not.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT attesting_agency_id FROM AgencyTrustAttestation
                 WHERE attesting_agency_id IN (4, 5) AND attested_agency_id = 2
                   AND context_id = %s AND revocation_date IS NULL
            """, (ctx_mv,))
            attested = {r['attesting_agency_id'] for r in cur.fetchall()}
        self.assertEqual(attested, {4, 5},
                         'both cross-attesting-agency attests should have taken effect')

    # -------------------------------------------------------------------
    # R10-1 / M2-1 — Per-procedure advisory-lock on uc11_close_epoch.
    # The lock domain is `polaris.zk.close-epoch` — a SINGLE shared key.
    # All epoch closures globally serialize (the per-procedure lock rather
    # than per-entity, because epoch_id is assigned by SERIAL and we want
    # to prevent gap-skipping under concurrent closure).
    # -------------------------------------------------------------------
    def test_uc11_close_epoch_serializes_under_lock(self):
        """Two parallel uc11_close_epoch calls must serialize at the
        per-procedure advisory lock. Without the lock, both threads could
        write TokenStateEpoch rows simultaneously, producing potentially
        unrelated epoch_id values out of natural order."""
        from psycopg2.extras import Json
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin = cur.fetchone()['user_id']

        # Two distinct payloads (different leaves) so each call is a real
        # epoch creation, not a duplicate.
        payloads = [
            ('aa' * 32,
             [{'token_id': 2, 'leaf_hash': 'bb' * 32, 'proof_path': []}]),
            ('cc' * 32,
             [{'token_id': 3, 'leaf_hash': 'dd' * 32, 'proof_path': []}]),
        ]

        def close_epoch(root_hex, leaves):
            return lambda cur: cur.execute(
                "CALL uc11_close_epoch(%s, %s, %s, %s)",
                (root_hex, datetime.now() + timedelta(days=10), admin, Json(leaves)))

        self.assertContends(close_epoch(*payloads[0]), close_epoch(*payloads[1]),
                            'Concurrent epoch closures')

    # -------------------------------------------------------------------
    # Does the procedure TAKE its lock at all? The same-entity tests above
    # check the consequence of the lock (no split batch, no double recovery),
    # which is the right thing to assert but not a reliable detector: the race
    # they watch for only manifests when the threads interleave, and on
    # 2026-09-14 close_anchor_batch was reinstalled with its
    # pg_advisory_xact_lock line deleted and the outcome test passed anyway.
    # These four ask the lock manager instead, one per remaining domain.
    # -------------------------------------------------------------------
    def test_uc8_revoke_takes_its_advisory_lock(self):
        """Two tokens, one agency. The agency is the key, so the second waits."""
        with self._new_conn() as conn, conn.cursor() as cur:
            set_discretion_bound(cur, (2,), 95.00,
                                 why='C9 lock-presence test: permissive for agency 2')
            conn.commit()

        def seed(label):
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                    VALUES (%s, '1990-01-01', 'US-PA') RETURNING individual_id
                """, ('C9 LOCKPRESENCE %s' % label,))
                iid = cur.fetchone()['individual_id']
                cur.execute("""
                    INSERT INTO IdentityToken
                        (token_value, physical_serial, hardware_model,
                         biometric_binding_type, individual_id, issuing_agency_id,
                         algorithm_id, status, issued_date, expiration_date)
                    VALUES (%s, %s, 'TitanQ-3', 'IRIS', %s, 2, 1, 'RESERVE',
                            CURRENT_TIMESTAMP, (polaris_utc_date() + INTERVAL '10 years')::date)
                    RETURNING token_id
                """, ('TKN-C9-LP-%s' % label, 'SN-C9-LP-%s' % label, iid))
                tid = cur.fetchone()['token_id']
                cur.execute("SELECT set_config('polaris.actor_agency_id', '2', false)")
                cur.execute("SELECT set_config('polaris.reason_code', 'TEST_SEED', false)")
                cur.execute("UPDATE IdentityToken SET status='ACTIVE', "
                            "activated_date=CURRENT_TIMESTAMP WHERE token_id=%s", (tid,))
                conn.commit()
            return tid

        def revoke(token_id):
            return lambda cur: cur.execute(
                "CALL uc8_revoke_token(%s, %s, %s, %s, %s)",
                (token_id, 2, 'ADMINISTRATIVE',
                 'https://crl.idtoken.gov/test/lockpresence.crl', None))

        self.assertContends(revoke(seed('a')), revoke(seed('b')),
                            'Same-agency revocations')

    def test_uc6_migrate_takes_its_advisory_lock(self):
        """One token, two migrations. The lock is taken before any validation,
        so the second blocks at the lock rather than on the token's state."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO Individual (legal_name, date_of_birth, jurisdiction)
                VALUES ('C9 lockpresence migrate', '1990-01-01', 'US-PA')
                RETURNING individual_id
            """)
            iid = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, hardware_model,
                     biometric_binding_type, individual_id, issuing_agency_id,
                     algorithm_id, status, issued_date, expiration_date)
                VALUES (%s, %s, 'TitanQ-3', 'IRIS', %s, 1, 1, 'RESERVE',
                        CURRENT_TIMESTAMP, (polaris_utc_date() + INTERVAL '10 years')::date)
                RETURNING token_id
            """, ('TKN-C9-LPM-%s' % iid, 'SN-C9-LPM-%s' % iid, iid))
            tid = cur.fetchone()['token_id']
            cur.execute("INSERT INTO TokenSignature (token_id, algorithm_id, "
                        "signature_bytes) VALUES (%s, 1, %s)",
                        (tid, ('LPSEED_%d' % tid).encode()))
            conn.commit()

        # Two DIFFERENT target algorithms. TokenSignature is unique on
        # (token_id, algorithm_id), so migrating to 2 and to 3 writes different
        # rows and nothing but the advisory key -- token_id -- is shared. The
        # first version of this test migrated to algorithm 2 twice and blocked on
        # that unique index rather than on the lock, so it passed against a
        # procedure with no lock at all.
        def migrate(algorithm_id):
            return lambda cur: cur.execute(
                "CALL uc6_migrate_algorithm(%s, %s, %s, %s)",
                (tid, algorithm_id, ('LPMIG_%d' % algorithm_id).encode(), False))

        self.assertContends(migrate(2), migrate(3), 'Same-token migrations')

    # 2026-10-01. Locks taken in FUNCTIONS, which check_advisory_locks_have_a_contention_test
    # did not see until then: the holder key register's per-credential lock (a domain with an
    # underscore, which the check did not read) and the population counts' fold lock.

    def _live_credential(self, tag):
        """A fresh ACTIVE credential with a live signature, for a lock test of its own."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("INSERT INTO Individual (legal_name, date_of_birth, jurisdiction) "
                        "VALUES (%s, '1990-01-01', 'US-PA') RETURNING individual_id", ('C9 ' + tag,))
            iid = cur.fetchone()['individual_id']
            cur.execute("""
                INSERT INTO IdentityToken
                    (token_value, physical_serial, biometric_binding_type, individual_id,
                     issuing_agency_id, algorithm_id, status, issued_date, activated_date,
                     expiration_date)
                VALUES (%s, %s, 'NONE', %s, 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
                        (polaris_utc_date() + INTERVAL '10 years')::date)
                RETURNING token_id
            """, ('TKN-C9-%s-%s' % (tag, iid), 'SN-C9-%s-%s' % (tag, iid), iid))
            tid = cur.fetchone()['token_id']
            cur.execute("INSERT INTO TokenSignature (token_id, algorithm_id, signature_bytes) "
                        "VALUES (%s, 1, %s)", (tid, ('C9_%s_%d' % (tag, tid)).encode()))
            conn.commit()
        return tid

    def test_holder_key_events_on_two_credentials_do_not_block(self):
        a, b = self._live_credential('hk-a'), self._live_credential('hk-b')

        def bind(tid, key_byte):
            return lambda cur: cur.execute(
                "SELECT uc_record_holder_key_event(%s, %s, 'ML-DSA-65', 'bound')", (tid, key_byte * 32))
        self.assertDoesNotContend(bind(a, 'ab'), bind(b, 'cd'), 'Holder keys bound to two credentials')

    def test_holder_key_events_on_one_credential_serialize(self):
        """The register's writer takes its lock before reading the key in force, so a second
        change to the same credential waits at the lock, not at a constraint."""
        a = self._live_credential('hk-one')

        def bind(key_byte):
            return lambda cur: cur.execute(
                "SELECT uc_record_holder_key_event(%s, %s, 'ML-DSA-65', 'bound')", (a, key_byte * 32))
        self.assertContends(bind('ab'), bind('cd'), 'Two holder key changes to one credential')

    def test_a_population_recount_takes_its_lock(self):
        """The holder is a fold with nothing pending, which holds the lock and no row. Two
        recounts contend on the rows each deletes, lock or no lock: measured on 2026-10-02, the
        recount-against-recount version of this test passed with the recount's lock deleted."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT uc_fold_population_counts()")
            conn.commit()
        self.assertContends(lambda cur: cur.execute("SELECT uc_fold_population_counts()"),
                            lambda cur: cur.execute("SELECT uc_rebuild_population_counts()"),
                            'A population recount while a fold holds the lock')

    def test_an_enrolment_fold_skips_while_a_rebuild_holds_the_lock(self):
        """uc_fold_enrollment_counts takes its lock with pg_try_advisory_xact_lock, and the rebuild
        takes the same lock outright: while a rebuild is open, a fold returns at once having
        folded nothing. Without the rebuild's lock the fold would reach the changes the rebuild
        is deleting and wait on them, which the short lock_timeout turns into a failure; without
        the fold's, the same. The control folds every change once nobody holds the lock."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("UPDATE Individual SET jurisdiction = 'US-CA' "
                        "WHERE individual_id = (SELECT min(individual_id) FROM Individual)")
            cur.execute("SELECT count(*) AS n FROM EnrollmentCountDelta")
            self.assertGreater(cur.fetchone()['n'], 0, 'control: there are changes to fold')
            conn.commit()
        holder = self._new_conn()
        try:
            with holder.cursor() as cur:
                cur.execute("SELECT uc_rebuild_enrollment_counts()")   # holds the lock, left open
            probe = self._new_conn()
            try:
                with probe.cursor() as cur:
                    cur.execute("SET lock_timeout = '2s'")
                    cur.execute("SELECT uc_fold_enrollment_counts() AS folded")
                    self.assertEqual(cur.fetchone()['folded'], 0,
                                     'a fold ran while a rebuild held the lock')
                probe.commit()
            finally:
                probe.close()
        finally:
            holder.rollback()
            holder.close()
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM EnrollmentCountDelta")
            pending = cur.fetchone()['n']
            cur.execute("SELECT uc_fold_enrollment_counts() AS folded")
            self.assertEqual(cur.fetchone()['folded'], pending)
            conn.commit()
            cur.execute("""
                SELECT jurisdiction, status, n FROM EnrollmentCount WHERE n <> 0
                EXCEPT
                SELECT jurisdiction, current_status, count(*) FROM IndividualCurrentEnrollment GROUP BY 1, 2""")
            self.assertEqual(cur.fetchall(), [], 'the folded totals differ from a full count')

    def test_a_fold_skips_while_a_recount_holds_the_lock(self):
        """uc_fold_population_counts takes its lock with pg_try_advisory_xact_lock: while a
        recount holds it, a fold returns at once having folded nothing, and leaves the changes
        for the next fold. A try-lock never waits, so assertContends cannot see it; this does."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("UPDATE IdentityToken SET status = 'LOST' WHERE token_id = 4")
            conn.commit()
        holder = self._new_conn()
        try:
            with holder.cursor() as cur:
                cur.execute("SELECT uc_rebuild_population_counts()")   # holds the lock, left open
            probe = self._new_conn()
            try:
                with probe.cursor() as cur:
                    cur.execute("SET lock_timeout = '2s'")
                    cur.execute("SELECT uc_fold_population_counts() AS folded")
                    self.assertEqual(cur.fetchone()['folded'], 0,
                                     'a fold ran while a recount held the lock')
                probe.commit()
            finally:
                probe.close()
        finally:
            holder.rollback()
            holder.close()
        # The control: with nobody holding the lock, the fold folds every change there is, and
        # the totals it leaves equal a full count. The change above is a pure decrement of two
        # existing totals (an ACTIVE credential and its live signature), the case INSERT ... ON
        # CONFLICT refused before the fold updated existing totals in their own statement.
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM PopulationCountDelta")
            pending = cur.fetchone()['n']
            cur.execute("SELECT uc_fold_population_counts() AS folded")
            self.assertEqual(cur.fetchone()['folded'], pending)
            conn.commit()
            cur.execute("SELECT count(*) AS n FROM PopulationCountDelta")
            self.assertEqual(cur.fetchone()['n'], 0)
            cur.execute("""
                SELECT facet, agency_id, item, n FROM PopulationCount WHERE n <> 0
                EXCEPT
                (SELECT 'credential_status', issuing_agency_id, status, count(*)
                   FROM IdentityToken GROUP BY 2, 3
                 UNION ALL
                 SELECT 'live_signature', t.issuing_agency_id, s.algorithm_id::TEXT, count(*)
                   FROM TokenSignature s JOIN IdentityToken t ON t.token_id = s.token_id
                  WHERE s.deprecation_date IS NULL AND t.status = 'ACTIVE' GROUP BY 2, 3)""")
            self.assertEqual(cur.fetchall(), [], 'a folded total disagrees with a full count')

    def _a_fold_holding_only_its_lock(self):
        """A holder for the activity lock and nothing else: a fold, once nothing is pending, takes
        the lock and touches no row, so a probe that waits on it waits on the lock alone. (Two
        recounts would contend on the rows each deletes, lock or no lock: measured, that test
        stayed green with the recount's lock deleted.)"""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT uc_fold_activity_rollups()")
            conn.commit()
        return lambda cur: cur.execute("SELECT uc_fold_activity_rollups()")

    def test_a_recount_waits_for_the_activity_fold(self):
        """uc_rebuild_activity_rollups takes the fold's lock outright before anything else: its
        own fold only tries the lock, and a recount that went ahead while another fold ran would
        delete totals under it (lab/strategy/009, step 4)."""
        self.assertContends(self._a_fold_holding_only_its_lock(),
                            lambda cur: cur.execute("SELECT uc_rebuild_activity_rollups()"),
                            'A recount while a fold holds the activity lock')

    def test_a_purge_waits_for_the_activity_fold(self):
        """uc_archive_purge folds the activity rollups and then deletes the hourly rows before its
        cutoff under the fold's lock, so it never deletes an hour a fold is writing."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE role = 'admin' AND is_active "
                        "ORDER BY user_id LIMIT 1")
            admin = cur.fetchone()['user_id']
        purge = lambda cur: cur.execute(  # noqa: E731
            "CALL uc_archive_purge(now() - INTERVAL '3650 days', 'file:///x', repeat('a', 64), %s)",
            (admin,))
        self.assertContends(self._a_fold_holding_only_its_lock(), purge,
                            'A purge while a fold holds the activity lock')

    def test_an_activity_fold_skips_while_a_recount_holds_the_lock(self):
        """uc_fold_activity_rollups takes its lock with pg_try_advisory_xact_lock: while a recount
        holds it, a fold returns at once having folded nothing, and leaves the counts for the next
        fold. The control folds every pending count once nobody holds the lock, and the hours it
        leaves equal a recount of the events."""
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("INSERT INTO VerificationEvent (token_id, requesting_agency_id, context_id, "
                        "outcome, disclosure_level) SELECT NULL, min(agency_id), "
                        "(SELECT min(context_id) FROM VerificationContext), 'FAILURE', 'ZERO_KNOWLEDGE' "
                        "FROM Agency")
            conn.commit()
            cur.execute("SELECT count(*) AS n FROM VerificationRollupDelta")
            self.assertGreater(cur.fetchone()['n'], 0, 'control: there are counts to fold')
        holder = self._new_conn()
        try:
            with holder.cursor() as cur:
                cur.execute("SELECT uc_rebuild_activity_rollups()")   # holds the lock, left open
            probe = self._new_conn()
            try:
                with probe.cursor() as cur:
                    cur.execute("SET lock_timeout = '2s'")
                    cur.execute("SELECT uc_fold_activity_rollups() AS folded")
                    self.assertEqual(cur.fetchone()['folded'], 0,
                                     'a fold ran while a recount held the lock')
                probe.commit()
            finally:
                probe.close()
        finally:
            holder.rollback()
            holder.close()
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM VerificationRollupDelta")
            pending = cur.fetchone()['n']
            cur.execute("SELECT uc_fold_activity_rollups() AS folded")
            self.assertGreaterEqual(cur.fetchone()['folded'], pending)
            conn.commit()
            cur.execute("""
                SELECT bucket, requesting_agency_id, context_id, outcome, disclosure_level, n
                  FROM VerificationRollup
                 WHERE bucket >= date_trunc('hour', now()) - INTERVAL '1 hour'
                EXCEPT
                SELECT date_trunc('hour', event_timestamp), requesting_agency_id, context_id,
                       outcome, disclosure_level, count(*)
                  FROM VerificationEvent
                 WHERE event_timestamp >= date_trunc('hour', now()) - INTERVAL '1 hour'
                 GROUP BY 1, 2, 3, 4, 5""")
            self.assertEqual(cur.fetchall(), [], 'a folded hour disagrees with a recount')

    # uc9_complete_recovery's advisory lock is NOT independently observable, and
    # this is where a test proving it takes one would go. The key is
    # claimed_individual_id; the procedure then loads the RecoveryRequest FOR
    # UPDATE. `uq_one_pending_recovery_per_individual` is a partial unique index
    # allowing one PENDING recovery per individual, so any two calls that share the
    # advisory key necessarily target the SAME row and would serialize on the row
    # lock whether or not the advisory lock existed. A test here would block either
    # way: it was written, it passed against uc9_complete_recovery with the
    # pg_advisory_xact_lock line deleted, and it was removed rather than kept as a
    # green result that means nothing. The lock is not redundant -- it closes the
    # window before the SELECT -- but from outside the procedure the two are
    # indistinguishable, and saying so is worth more than a test that cannot tell.

    # close_anchor_batch's advisory lock is NOT independently observable either,
    # and for the same shape of reason as uc9's. The key is algorithm_id and the
    # procedure batches EVERY pending row under that algorithm, so two calls that
    # share the key necessarily target the same rows. Holding the first open does
    # not help: under READ COMMITTED the probe cannot see the holder's uncommitted
    # batching, reads the same pending set, and blocks on the UPDATE whether or not
    # the advisory lock is there. Written, measured against close_anchor_batch with
    # its pg_advisory_xact_lock line deleted, passed, and removed. What the lock
    # buys is that the second caller never READS the stale set in the first place,
    # and that difference is invisible from outside the procedure.

    def test_uc10_attest_and_revoke_share_one_lock_key(self):
        """An attest and a revoke under the same attesting agency serialize.

        The comment above this block has claimed this since R11-3 and nothing
        measured it. The two procedures reach the same key by different routes:
        uc10_attest_trust hashes its p_attesting_id PARAMETER, while
        uc10_revoke_attestation SELECTs attesting_agency_id out of the attestation
        row and hashes that. Nothing checked that the two routes agree, and a
        derivation reading the wrong column would leave the claim standing in a
        comment while the operations ran concurrently.

        The rows are disjoint -- the attest INSERTs a new attestation, the revoke
        UPDATEs an existing one -- so the key is the only thing they share.
        """
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin = cur.fetchone()['user_id']
            cur.execute("SELECT context_id FROM VerificationContext "
                        "WHERE context_type='VOTING'")
            ctx_voting = cur.fetchone()['context_id']
            cur.execute("SELECT context_id FROM VerificationContext "
                        "WHERE context_type='MOTOR_VEHICLE'")
            ctx_mv = cur.fetchone()['context_id']
            # An attestation BY agency 4 that the revoke can act on. Attesting
            # agency 4 is what both operations will lock on.
            cur.execute("""
                INSERT INTO AgencyTrustAttestation
                    (attesting_agency_id, attested_agency_id, context_id,
                     attested_date, valid_until, signed_by)
                VALUES (4, 3, %s, CURRENT_TIMESTAMP,
                        (polaris_utc_date() + INTERVAL '180 days')::date, %s)
                RETURNING attestation_id
            """, (ctx_voting, admin))
            attestation_id = cur.fetchone()['attestation_id']
            conn.commit()

        def attest(cur):
            cur.execute("CALL uc10_attest_trust(%s, %s, %s, %s, %s)",
                        (4, 2, ctx_mv,
                         (datetime.now(timezone.utc).date() + timedelta(days=180)), admin))

        def revoke(cur):
            cur.execute("CALL uc10_revoke_attestation(%s, %s, %s)",
                        (attestation_id, 'C9_LOCK_KEY_TEST', admin))

        self.assertContends(attest, revoke, 'Attest racing a revoke, same agency')

    def test_uc11_close_epoch_both_rows_committed(self):
        """Sanity check: after the two threads above finish, both epoch
        rows are committed (serialization, not loss-of-write)."""
        from psycopg2.extras import Json
        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT user_id FROM AppUser WHERE username='admin'")
            admin = cur.fetchone()['user_id']

        payloads = [
            ('e' * 64,
             [{'token_id': 2, 'leaf_hash': 'aa' * 32, 'proof_path': []}]),
            ('f' * 64,
             [{'token_id': 3, 'leaf_hash': 'bb' * 32, 'proof_path': []}]),
        ]

        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM TokenStateEpoch")
            count_before = cur.fetchone()['n']

        def close(root_hex, leaves):
            with self._new_conn() as conn, conn.cursor() as cur:
                cur.execute(
                    "CALL uc11_close_epoch(%s, %s, %s, %s)",
                    (root_hex,
                     datetime.now() + timedelta(days=10),
                     admin,
                     Json(leaves)))
                conn.commit()

        threads = [
            threading.Thread(target=close, args=(r, ls))
            for r, ls in payloads
        ]
        for t in threads: t.start()
        for t in threads: t.join()

        with self._new_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM TokenStateEpoch")
            count_after = cur.fetchone()['n']
            self.assertEqual(count_after, count_before + 2,
                'Both epoch closures must commit; serialization, not loss')


# ============================================================================
# THE ATLAS ON THE ACTIVITY ROLLUPS (lab/strategy/009, step 4)
# ============================================================================

def _atlas_events(n, agency=3, context=1, outcome='SUCCESS', disclosure='ZERO_KNOWLEDGE',
                  minutes_ago=30):
    """n verifications, counted into the activity rollups by their trigger like any other. The
    sample has none by authority 3, so a question filtered to it answers for these alone. Only a
    FULL disclosure names a credential (token 2), and never with SUCCESS, which the database
    would hold to that credential's rules."""
    assert not (disclosure == 'FULL' and outcome == 'SUCCESS')
    _sql("INSERT INTO VerificationEvent (token_id, requesting_agency_id, context_id, "
         "                               event_timestamp, outcome, disclosure_level) "
         "SELECT %s, %s, %s, CURRENT_TIMESTAMP - make_interval(mins => %s), %s, %s "
         "  FROM generate_series(1, %s)",
         (2 if disclosure == 'FULL' else None, agency, context, minutes_ago, outcome, disclosure,
          n), fetch='none')


class _AtlasCase(PolarisTestCase):
    """The Atlas suites' base (lab/strategy/009, step 4): a cold cache for each test, a way to ask,
    and a way to switch withholding off so a test can hold every figure to the event tables."""

    def setUp(self):
        super().setUp()
        atlas_routes._atlas_cache_clear()
        self.addCleanup(atlas_routes._atlas_cache_clear)

    def _ask(self, path, status=200):
        r = self.client.get(path)
        self.assertEqual(r.status_code, status, (path, r.get_data(as_text=True)[:300]))
        return r.get_json()

    def _raw(self, where='TRUE', params=()):
        return _sql("SELECT count(*) AS n FROM VerificationEvent WHERE " + where, params,
                    fetch='one')['n']

    @contextmanager
    def _unwithheld(self):
        """Every count shown: the minimum cell size at zero, the cache cleared either side."""
        atlas_routes._atlas_cache_clear()
        with patch.object(atlas_routes, '_ATLAS_MIN_CELL', 0):
            yield
        atlas_routes._atlas_cache_clear()

    def _db_now(self):
        return _sql("SELECT LOCALTIMESTAMP AS t", fetch='one')['t']


class AtlasArithmeticTests(_AtlasCase):
    """With withholding off, every Atlas figure is the event tables' figure: the rollups the
    readers sum are kept by triggers on the events, and a reader that dropped a row, counted one
    twice or read the wrong grain would show here as a difference from a plain count."""

    def test_every_reader_counts_every_verification_in_the_window(self):
        """window=all: the series, every breakdown, the cross-tab, the heatmap, the stacked bands,
        the regions and the headline all come to the events recorded, zero-knowledge ones
        included (C6: counted, never located)."""
        _atlas_events(3, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(4)
        raw, zk = self._raw(), self._raw("disclosure_level = 'ZERO_KNOWLEDGE'")
        self.assertGreater(zk, 0)
        with self._unwithheld():
            series = self._ask('/api/atlas/series?window=all&buckets=60')
            self.assertEqual((series['totals']['n_total'], series['totals']['n_zk']), (raw, zk))
            self.assertEqual(sum(p['n_total'] for p in series['points']), raw)
            for dim in ('agency', 'context', 'outcome', 'disclosure', 'algorithm', 'jurisdiction'):
                d = self._ask('/api/atlas/breakdown?window=all&dimension=' + dim)
                self.assertEqual(sum(c['n_total'] for c in d['categories']), raw, dim)
            for col in ('outcome', 'disclosure'):
                x = self._ask('/api/atlas/crosstab?window=all&row=context&col=' + col)
                self.assertEqual(sum(c['n'] for c in x['cells']), raw, col)
                self.assertEqual(sum(r['total'] for r in x['rows']), raw, col)
            heat = self._ask('/api/atlas/heatmap?window=all')
            self.assertEqual(sum(c['n'] for c in heat['cells']), raw)
            stacked = self._ask('/api/atlas/stacked?window=all&dimension=agency&buckets=60')
            self.assertEqual(sum(sum(p['values'].values()) for p in stacked['points']), raw)
            geo = self._ask('/api/atlas/geo/jurisdictions?window=all')
            self.assertEqual(sum(r['n_total'] for r in geo['regions'] + geo['unplaced'])
                             + geo['elsewhere'], raw)
            stats = self._ask('/api/atlas/stats?window=all')
            self.assertEqual((stats['n_verifs'], stats['n_full']),
                             (raw, self._raw("disclosure_level = 'FULL'")))

    def test_a_failure_is_every_outcome_but_success_in_every_reader(self):
        """One meaning across the page. Until 2026-10-02 the headline and the map counted FAILURE
        alone and the series, the heatmap and the breakdowns every outcome but SUCCESS, so the
        map's 'failures' and the overview's 'non-success' were two numbers under one word."""
        _atlas_events(6, outcome='UNAUTHORIZED', disclosure='SELECTIVE')
        _atlas_events(5, outcome='EXPIRED', disclosure='SELECTIVE')
        _atlas_events(7, outcome='FAILURE', disclosure='SELECTIVE')
        raw = self._raw("outcome <> 'SUCCESS'")
        with self._unwithheld():
            self.assertEqual(self._ask('/api/atlas/stats?window=all')['n_failures'], raw)
            self.assertEqual(self._ask('/api/atlas/series?window=all')['totals']['n_failure'], raw)
            heat = self._ask('/api/atlas/heatmap?window=all')
            self.assertEqual(sum(c['n_failure'] for c in heat['cells']), raw)
            geo = self._ask('/api/atlas/geo/jurisdictions?window=all')
            self.assertEqual(sum(r['n_failure'] for r in geo['regions'] + geo['unplaced']), raw)
            bd = self._ask('/api/atlas/breakdown?window=all&dimension=context')
            self.assertEqual(sum(c['n_failure'] for c in bd['categories']), raw)

    def test_the_lifecycle_stream_counts_every_transition(self):
        """A transition no authority made is counted as 'System / device', not dropped."""
        _sql("INSERT INTO TokenLifecycleEvent (token_id, actor_agency_id, event_type) "
             "VALUES (1, NULL, 'DEVICE_BOUND'), (1, NULL, 'DEVICE_REVOKED')", fetch='none')
        raw = _sql("SELECT count(*) AS n FROM TokenLifecycleEvent", fetch='one')['n']
        lost = _sql("SELECT count(*) AS n FROM TokenLifecycleEvent "
                    " WHERE event_type IN ('REVOKED', 'LOST')", fetch='one')['n']
        with self._unwithheld():
            for dim in ('agency', 'event_type'):
                d = self._ask('/api/atlas/breakdown?window=all&kind=lifecycle&dimension=' + dim)
                self.assertEqual(sum(c['n_total'] for c in d['categories']), raw, dim)
            agencies = self._ask('/api/atlas/breakdown?window=all&kind=lifecycle&dimension=agency')
            self.assertIn('System / device', [c['label'] for c in agencies['categories']])
            series = self._ask('/api/atlas/series?window=all&kind=lifecycle')
            self.assertEqual((series['totals']['n_total'], series['totals']['n_failure']),
                             (raw, lost))
            self.assertEqual(self._ask('/api/atlas/stats?window=all')['n_lifecycles'], raw)
            x = self._ask('/api/atlas/crosstab?window=all&kind=lifecycle&row=agency&col=event_type')
            self.assertEqual(sum(c['n'] for c in x['cells']), raw)

    def test_a_filter_narrows_every_reader_to_its_slice(self):
        """outcomes, disclosure, context and authority reach every reader's SQL, and an
        authority written with leading zeros is that authority."""
        _atlas_events(6, context=4, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(5, context=1)
        cases = (('outcomes=FAILURE', "outcome = 'FAILURE'"),
                 ('outcomes=anomalies', "outcome <> 'SUCCESS'"),
                 ('outcomes=FAILURE,UNAUTHORIZED,EXPIRED', "outcome <> 'SUCCESS'"),
                 ('disclosure=ZERO_KNOWLEDGE', "disclosure_level = 'ZERO_KNOWLEDGE'"),
                 ('disclosure=SELECTIVE,FULL', "disclosure_level <> 'ZERO_KNOWLEDGE'"),
                 ('contexts=TRAVEL', "context_id = 4"),
                 ('agencies=3', "requesting_agency_id = 3"),
                 ('agencies=0003', "requesting_agency_id = 3"))
        with self._unwithheld():
            for q, where in cases:
                with self.subTest(q):
                    raw = self._raw(where)
                    self.assertGreater(raw, 0)
                    self.assertLess(raw, self._raw())
                    series = self._ask('/api/atlas/series?window=all&' + q)
                    self.assertEqual(series['totals']['n_total'], raw)
                    bd = self._ask('/api/atlas/breakdown?window=all&dimension=agency&' + q)
                    self.assertEqual(sum(c['n_total'] for c in bd['categories']), raw)
                    heat = self._ask('/api/atlas/heatmap?window=all&' + q)
                    self.assertEqual(sum(c['n'] for c in heat['cells']), raw)
                    geo = self._ask('/api/atlas/geo/jurisdictions?window=all&' + q)
                    self.assertEqual(sum(r['n_total'] for r in geo['regions'] + geo['unplaced']),
                                     raw)
            stats = self._ask('/api/atlas/stats?window=all&agencies=3')
            self.assertEqual(stats['n_verifs'], self._raw('requesting_agency_id = 3'))

    def test_the_facet_counts_each_authority_without_its_own_selection(self):
        _atlas_events(6)
        with self._unwithheld():
            d = self._ask('/api/atlas/facet/agencies?window=all&limit=50&agencies=1')
            got = {a['agency_id']: a['n_total'] for a in d['results']}
            for a in _sql("SELECT agency_id FROM Agency"):
                self.assertEqual(got[a['agency_id']],
                                 self._raw('requesting_agency_id = %s', (a['agency_id'],)))


class AtlasWithholdingTests(_AtlasCase):
    """Small cells are withheld (lab/strategy/009, step 4): a count of one at a known authority,
    context and hour tells someone who knows who was there what happened to them, and the Atlas,
    unlike the verification log, records no read. k is atlas_routes._ATLAS_MIN_CELL, five."""

    CAL = 'California Identity Office'      # authority 3: no verification in the sample

    def test_the_minimum_is_five(self):
        self.assertEqual((atlas_routes._ATLAS_MIN_CELL, atlas_routes._ATLAS_NARROW_SCOPE), (5, 50))
        self.assertEqual(self._ask('/api/atlas/stats?window=all')['min_cell'], 5)

    def test_a_fixed_dimension_lists_every_value_and_withholds_the_small_and_the_empty(self):
        """Four FAILUREs and nothing else: a listed 4 is the small cell itself, and a listed 0
        says 'none' where a withheld one says 'fewer than five'."""
        _atlas_events(4, outcome='FAILURE', disclosure='SELECTIVE')
        for dim, values in (('outcome', atlas_routes._ATLAS_OUTCOMES),
                            ('disclosure', atlas_routes._ATLAS_DISCLOSURES),
                            ('context', atlas_routes._ATLAS_CONTEXTS)):
            d = self._ask('/api/atlas/breakdown?window=all&agencies=3&dimension=' + dim)
            self.assertEqual([c['label'] for c in d['categories']], list(values), dim)
            self.assertEqual({c['n_total'] for c in d['categories']}, {None}, dim)

    def test_a_count_is_withheld_when_the_rest_of_its_whole_is_small(self):
        """SUCCESS 10 of 12 gives FAILURE 2 back: a part is shown only when it and the rest of
        its scope both reach the minimum."""
        _atlas_events(10)
        _atlas_events(2, outcome='FAILURE', disclosure='SELECTIVE')
        url = '/api/atlas/breakdown?window=all&dimension=outcome&agencies=3'
        got = {c['label']: c['n_total'] for c in self._ask(url)['categories']}
        self.assertEqual(got, dict.fromkeys(atlas_routes._ATLAS_OUTCOMES))
        _atlas_events(4, outcome='FAILURE', disclosure='SELECTIVE')
        atlas_routes._atlas_cache_clear()
        got = {c['label']: c['n_total'] for c in self._ask(url)['categories']}
        self.assertEqual(got, {'SUCCESS': 10, 'FAILURE': 6, 'EXPIRED': None, 'UNAUTHORIZED': None})

    def test_a_share_is_withheld_as_its_count_is(self):
        _atlas_events(9)                                       # zero-knowledge
        _atlas_events(3, outcome='FAILURE', disclosure='SELECTIVE')
        stats = self._ask('/api/atlas/stats?window=all&agencies=3')
        self.assertEqual((stats['n_verifs'], stats['zk_pct'], stats['n_failures']),
                         (12, None, None))
        _atlas_events(2, outcome='FAILURE', disclosure='SELECTIVE')
        atlas_routes._atlas_cache_clear()
        stats = self._ask('/api/atlas/stats?window=all&agencies=3')
        self.assertEqual((stats['n_verifs'], stats['zk_pct'], stats['n_failures']), (14, 64, 5))

    def test_an_open_list_folds_its_small_categories_into_one_row(self):
        """An authority with three verifications is not named: listed with its count withheld,
        it would still say that it had activity."""
        _atlas_events(3)
        _atlas_events(9, agency=2)
        d = self._ask('/api/atlas/breakdown?window=all&dimension=agency')
        labels = [c['label'] for c in d['categories']]
        self.assertIn('Pennsylvania Identity Bureau', labels)
        self.assertNotIn(self.CAL, labels)
        self.assertEqual(labels[-1], atlas_routes._ATLAS_FOLDED)
        self.assertTrue(d['categories'][-1]['folded'])
        self.assertEqual(d['count'], len(d['categories']))
        # The stacked bands fold the same way: a small authority is in 'Other', never a band.
        st = self._ask('/api/atlas/stacked?window=all&dimension=agency&buckets=12')
        self.assertNotIn(self.CAL, st['labels'])
        self.assertIn('Pennsylvania Identity Bureau', st['labels'])

    def test_the_facet_lists_every_authority_in_name_order(self):
        """Ranked by volume, or listing only the active, the facet would say which small
        authorities had activity even with their counts withheld."""
        _atlas_events(3)
        d = self._ask('/api/atlas/facet/agencies?window=all&limit=50')
        self.assertEqual([a['name'] for a in d['results']],
                         [r['name'] for r in _sql("SELECT name FROM Agency ORDER BY name, agency_id")])
        self.assertIsNone({a['name']: a['n_total'] for a in d['results']}[self.CAL])

    def test_a_cross_tab_total_is_withheld_when_it_would_give_a_small_cell_back(self):
        """SUCCESS 20, FAILURE 6 and EXPIRED 2: shown, the total less the shown cells is the 2
        the cell withholds. With the withheld cells summing to five or more it can be shown."""
        _atlas_events(20)
        _atlas_events(6, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(2, outcome='EXPIRED', disclosure='SELECTIVE')

        def row():
            atlas_routes._atlas_cache_clear()
            x = self._ask('/api/atlas/crosstab?window=all&row=agency&col=outcome')
            cells = {c['col']: c['n'] for c in x['cells'] if c['row'] == self.CAL}
            return cells, [r['total'] for r in x['rows'] if r['label'] == self.CAL][0]
        cells, total = row()
        self.assertEqual(cells, {'SUCCESS': 20, 'FAILURE': 6, 'EXPIRED': None,
                                 'UNAUTHORIZED': None})
        self.assertIsNone(total)
        _atlas_events(3, outcome='UNAUTHORIZED', disclosure='SELECTIVE')    # withheld: 2 + 3
        cells, total = row()
        self.assertEqual((cells['UNAUTHORIZED'], total), (None, 31))

    def test_every_bucket_and_cell_is_listed_and_a_quiet_one_withheld(self):
        """A series and the heatmap are filled: a missing bucket would read as none where a
        withheld one reads as fewer than five."""
        _atlas_events(6, minutes_ago=30)
        _atlas_events(6, minutes_ago=200)
        heat = self._ask('/api/atlas/heatmap?window=24h&agencies=3')
        self.assertEqual(sorted((c['dow'], c['hour']) for c in heat['cells']),
                         [(d, h) for d in range(1, 8) for h in range(24)])
        self.assertEqual(sorted(c['n'] for c in heat['cells'] if c['n'] is not None), [6, 6])
        series = self._ask('/api/atlas/series?window=24h&buckets=24&agencies=3')
        width = timedelta(seconds=series['bucket_seconds'])
        since = datetime.fromisoformat(series['since'])
        self.assertEqual([p['ts'] for p in series['points']],
                         [(since + i * width).strftime('%Y-%m-%dT%H:%M:%S')
                          for i in range(len(series['points']))])
        self.assertEqual(sorted(p['n_total'] for p in series['points'] if p['n_total'] is not None),
                         [6, 6])
        self.assertEqual(series['totals']['n_total'], 12)

    def test_a_region_with_fewer_than_five_is_not_drawn(self):
        """A mark on the map would say the jurisdiction had activity; it joins 'elsewhere'."""
        _atlas_events(3)                          # US-CA
        _atlas_events(9, agency=2)                # US-PA
        geo = self._ask('/api/atlas/geo/jurisdictions?window=24h')
        drawn = {r['jurisdiction'] for r in geo['regions'] + geo['unplaced']}
        self.assertIn('US-PA', drawn)
        self.assertNotIn('US-CA', drawn)
        self.assertFalse(geo['truncated'])

    def test_a_region_is_placed_from_reference_data_never_from_an_event(self):
        """The rollups hold no coordinate: a region's point is the jurisdiction's, from the
        reference file beside the page, wherever its verifications said they were."""
        _sql("INSERT INTO VerificationEvent (requesting_agency_id, context_id, outcome, "
             "       disclosure_level, latitude, longitude) "
             "SELECT 3, 1, 'SUCCESS', 'SELECTIVE', -33.9, 18.4 FROM generate_series(1, 6)",
             fetch='none')
        with open(os.path.join(os.path.dirname(os.path.abspath(atlas_routes.__file__)), 'static',
                               'atlas-regions.json'), encoding='utf-8') as fh:
            ref = json.load(fh)['regions']['US-CA']
        (region,) = self._ask('/api/atlas/geo/jurisdictions?window=all&agencies=3')['regions']
        self.assertEqual((region['jurisdiction'], region['lat'], region['lon']),
                         ('US-CA', ref['lat'], ref['lon']))


class AtlasNarrowQuestionTests(_AtlasCase):
    """A question whose filtered window holds fewer than fifty events is answered, withheld as
    any, and written to the application log: who asked and what, never a count or a person
    (lab/strategy/009, step 4). A narrowing question leaves a trace, as a read of the
    verification log does, including when the cache answers it."""

    def _narrow_lines(self, url):
        with self.assertLogs(flask_app.app.logger, level='INFO') as logs:
            flask_app.app.logger.info('control')
            self._ask(url)
        return [m for m in logs.output if 'atlas narrow question' in m]

    def test_a_narrow_question_is_logged_each_time_it_is_asked(self):
        _atlas_events(7)
        url = '/api/atlas/breakdown?window=all&dimension=outcome&agencies=3'
        for attempt in ('computed', 'from the cache'):
            lines = self._narrow_lines(url)
            self.assertEqual(len(lines), 1, attempt)
            self.assertIn('asked breakdown', lines[0])
            self.assertIn('authority=3', lines[0])
            self.assertNotIn(' 7 ', lines[0], 'the log names no count')
        self.assertEqual(atlas_routes._atlas_cache_stats['hits'], 1)

    def test_a_broad_question_is_not_logged(self):
        _atlas_events(50)
        self.assertEqual(
            self._narrow_lines('/api/atlas/breakdown?window=all&dimension=outcome&agencies=3'), [])


class AtlasWindowTests(_AtlasCase):
    """The windows are the rollups': a window starts at the top of the hour (the day, past a
    week) that holds its nominal start, measured on the database's clock (rc.29), and says so."""

    ALIGN = {'1h': (timedelta(hours=1), 'hour'), '24h': (timedelta(hours=24), 'hour'),
             '7d': (timedelta(days=7), 'hour'), '30d': (timedelta(days=30), 'day')}

    def test_a_window_starts_at_the_top_of_its_hour_or_day(self):
        for window, (span, grain) in self.ALIGN.items():
            with self.subTest(window):
                before = self._db_now()
                d = self._ask('/api/atlas/stats?window=' + window)
                after = self._db_now()
                cut = {'hour': dict(minute=0, second=0, microsecond=0),
                       'day': dict(hour=0, minute=0, second=0, microsecond=0)}[grain]
                self.assertEqual(d['grain'], grain)
                self.assertIn(datetime.fromisoformat(d['since']),
                              {(before - span).replace(**cut), (after - span).replace(**cut)})
        d = self._ask('/api/atlas/stats?window=all')
        self.assertEqual((d['since'], d['grain']), (None, 'day'))

    def test_an_event_before_the_window_is_not_counted(self):
        """'1h' starts at most two hours back and '24h' at most twenty-five."""
        _atlas_events(5, outcome='UNAUTHORIZED', disclosure='SELECTIVE', minutes_ago=180)
        _atlas_events(6, outcome='UNAUTHORIZED', disclosure='SELECTIVE', minutes_ago=26 * 60)
        with self._unwithheld():
            def n(window):
                return self._ask('/api/atlas/series?agencies=3&window=' + window)['totals']['n_total']
            self.assertEqual((n('1h'), n('24h'), n('7d'), n('all')), (0, 5, 11, 11))

    def test_the_heatmap_says_where_its_hours_begin(self):
        """The heatmap reads the hourly rollup, which a purge shortens while the daily rollup
        keeps its days: for 'all' it says where its hours begin rather than claiming them all."""
        first = _sql("SELECT least((SELECT min(bucket) FROM VerificationRollup), "
                     "             (SELECT min(bucket) FROM VerificationRollupDelta)) AS h",
                     fetch='one')['h']
        d = self._ask('/api/atlas/heatmap?window=all')
        self.assertEqual((d['since'], d['grain']), (first.isoformat(), 'hour'))

    def test_a_series_never_has_more_buckets_than_asked(self):
        """The width was the window over the buckets rounded up, and at an exact multiple that
        cuts one bucket more than asked, the last starting at the window's end (C8)."""
        t0 = datetime(2026, 10, 1, 10, 0, 0)
        for hours in (1, 2, 23, 24, 25, 48, 167, 168, 169, 240, 241, 720, 721):
            for buckets in (1, 2, 7, 24, 48, 60, 240):
                for grain, unit in (('hour', 3600), ('day', 86400)):
                    until = t0 + timedelta(hours=hours)
                    width = atlas_routes._bucket_width(t0, until, buckets, grain)
                    with self.subTest(hours=hours, buckets=buckets, grain=grain):
                        self.assertLessEqual(len(atlas_routes._buckets(t0, until, width)), buckets)
                        self.assertEqual(width.total_seconds() % unit, 0)
        for n in (1, 13, 24, 60, 240):
            for window in ('1h', '24h', '7d', '30d', 'all'):
                d = self._ask('/api/atlas/series?window=%s&buckets=%d' % (window, n))
                self.assertLessEqual(len(d['points']), n, (window, n))
                self.assertEqual(d['buckets'], len(d['points']))


class AtlasParameterTests(_AtlasCase):
    """Every caller-chosen value is whitelisted or clamped before the SQL sees it (C8), and a
    malformed one is a 400 that says what was wrong."""

    def test_a_malformed_question_is_400(self):
        for path in ('/api/atlas/series?window=always', '/api/atlas/series?window=15min',
                     '/api/atlas/series?window=24', '/api/atlas/series?outcomes=NOT_AN_OUTCOME',
                     '/api/atlas/series?contexts=NOT_A_CONTEXT', '/api/atlas/series?disclosure=PARTIAL',
                     '/api/atlas/series?kind=banana', '/api/atlas/series?buckets=0',
                     '/api/atlas/series?buckets=241', '/api/atlas/series?buckets=nan',
                     '/api/atlas/stacked?dimension=evil',
                     '/api/atlas/stacked?dimension=context&buckets=9999',
                     '/api/atlas/stacked?kind=lifecycle&dimension=context',
                     '/api/atlas/breakdown?dimension=gender',
                     '/api/atlas/breakdown?kind=verification&dimension=event_type',
                     '/api/atlas/breakdown?dimension=agency&limit=0',
                     '/api/atlas/breakdown?dimension=agency&limit=many',
                     '/api/atlas/crosstab?row=gender&col=outcome',
                     '/api/atlas/crosstab?row=agency&col=religion',
                     '/api/atlas/crosstab?kind=verification&row=agency&col=event_type',
                     '/api/atlas/crosstab?row=agency&col=outcome&limit=-3',
                     '/api/atlas/facet/agencies?limit=-1', '/api/atlas/heatmap?kind=banana',
                     '/api/atlas/geo/jurisdictions?kind=banana', '/api/atlas/stats?window=1y'):
            with self.subTest(path):
                r = self.client.get(path)
                self.assertEqual(r.status_code, 400, r.get_data(as_text=True)[:200])
                self.assertTrue(r.get_json()['error'])
        # A refusal is a fixed sentence: it says what is accepted and never carries the request,
        # or a library's exception text, back (CWE-209; code scanning #379-#388).
        r = self.client.get('/api/atlas/series?outcomes=NOT_AN_OUTCOME')
        self.assertEqual(r.get_json()['error'],
                         "outcomes must be among ['SUCCESS', 'FAILURE', 'EXPIRED', 'UNAUTHORIZED']")
        for path, sent in (('/api/atlas/series?buckets=abc', 'abc'),
                           ('/api/atlas/stats?window=probe-1y', 'probe'),
                           ('/api/atlas/stats?window=all&agencies=12PROBE', 'PROBE'),
                           ('/api/atlas/stats?window=all&contexts=PROBE', 'PROBE'),
                           ('/api/atlas/series?outcomes=PROBE', 'PROBE')):
            with self.subTest(path):
                r = self.client.get(path)
                self.assertEqual(r.status_code, 400)
                self.assertNotIn(sent, r.get_data(as_text=True))
        self.assertEqual(self.client.get('/api/atlas/series?buckets=abc').get_json()['error'],
                         'a request parameter is not valid')
        r = self.client.get('/api/atlas/facet/agencies?window=all&limit=-1')
        self.assertEqual(r.get_json()['error'], 'limit must not be negative')

    def test_one_context_and_one_authority_at_a_time(self):
        """With a set, the answer for all but one would subtract from the answer for all."""
        for q, message in (('contexts=BANKING,TRAVEL', 'one context at a time'),
                           ('agencies=1,2', 'one authority at a time'),
                           ('agencies=1,', 'one authority at a time')):
            r = self.client.get('/api/atlas/breakdown?window=all&dimension=outcome&' + q)
            self.assertEqual((r.status_code, r.get_json()['error']), (400, message))

    def test_an_authority_is_written_in_ascii_digits(self):
        """str.isdigit() takes a superscript two and an Arabic-Indic three, which the SQL would
        then match as text against nothing."""
        for bad in ('%C2%B2', '%D9%A3', '1e3', '-1', '%2B1', '0x10', '12345678901'):
            with self.subTest(bad):
                r = self.client.get('/api/atlas/stats?window=all&agencies=' + bad)
                self.assertEqual(r.status_code, 400)
                self.assertIn('authority id must be an integer', r.get_json()['error'])

    def test_every_cap_holds_whatever_is_asked(self):
        cap = atlas_routes._ATLAS_MAX_CATEGORIES
        self.assertEqual(
            self._ask('/api/atlas/breakdown?window=all&dimension=agency&limit=100000')['limit'], cap)
        self.assertEqual(
            self._ask('/api/atlas/crosstab?window=all&row=agency&col=outcome&limit=100000')['limit'],
            cap)
        self.assertLessEqual(
            len(self._ask('/api/atlas/facet/agencies?window=all&limit=100000')['results']), cap)

    def test_a_cut_list_says_it_was_cut(self):
        """At the cap the quietest rows are in no row at all, and the answer says so rather than
        reading as every row there is."""
        _atlas_events(6, agency=1)
        _atlas_events(7, agency=2)
        d = self._ask('/api/atlas/breakdown?window=all&dimension=agency&limit=1')
        self.assertTrue(d['truncated'])
        x = self._ask('/api/atlas/crosstab?window=all&row=agency&col=outcome&limit=1')
        self.assertTrue(x['truncated'])
        self.assertFalse(self._ask('/api/atlas/crosstab?window=all&row=agency&col=outcome')['truncated'])
        with patch.object(atlas_routes, '_ATLAS_MAX_REGIONS', 1):
            self.assertTrue(self._ask('/api/atlas/geo/jurisdictions?window=all')['truncated'])

    def test_the_withdrawn_location_layers_are_gone(self):
        """The cluster and hexagon layers binned events by coordinate, and at street zoom a bin of
        one is a point; the timeline counted located events in a box (lab/strategy/009, step 4)."""
        for path in ('/api/atlas/clusters?bbox=-89,-179,89,179&grid=5',
                     '/api/atlas/hexbin?bbox=-89,-179,89,179&size=5',
                     '/api/atlas/timeline?bbox=-89,-179,89,179&buckets=24'):
            self.assertEqual(self.client.get(path).status_code, 404, path)


class AtlasCacheTests(_AtlasCase):
    """The cache answers a repeated question, keyed by the question, its window's start and whom
    it was answered for (AtlasCacheScopeTests)."""

    def test_a_repeated_question_is_answered_from_the_cache(self):
        self._ask('/api/atlas/breakdown?window=all&dimension=context')
        self._ask('/api/atlas/breakdown?window=all&dimension=context')
        d = self._ask('/api/atlas/cache-stats')
        self.assertEqual((d['misses'], d['hits'], d['current_entries']), (1, 1, 1))

    def test_two_windows_do_not_share_an_answer(self):
        _atlas_events(6, minutes_ago=20)
        with self._unwithheld():
            everything = self._ask('/api/atlas/series?window=all&agencies=3&buckets=10')
            _atlas_events(6, minutes_ago=26 * 60)
            hour = self._ask('/api/atlas/series?window=1h&agencies=3&buckets=10')
            self.assertEqual((everything['totals']['n_total'], hour['totals']['n_total']), (6, 6))
            again = self._ask('/api/atlas/series?window=all&agencies=3&buckets=10')
            self.assertEqual(again['totals']['n_total'], 6, 'the cached answer, not a recount')


class AtlasCompareTests(_AtlasCase):
    """compare=previous (lab/strategy/009 A4): each count beside the same count in the window of
    the same nominal length immediately before, withheld against that window's own scope, a
    change only where both counts are shown, and a mark where the failure share at least doubled
    with ten or more extra failures. Authorities 4, 5 and 6 are this class's: no other suite
    records a verification there, so each test's slice holds its own events alone."""

    def _count(self, agency, where, params):
        return self._raw('requesting_agency_id = %s AND ' + where, (agency,) + tuple(params))

    def test_the_window_before_is_counted_as_the_window_is(self):
        """Every compared figure is the event table's own count, on the hourly grain and on the
        daily, and the window before ends where this one starts."""
        _atlas_events(6, agency=6, context=5, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(11, agency=6, context=5, outcome='FAILURE', disclosure='SELECTIVE',
                      minutes_ago=26 * 60)
        _atlas_events(8, agency=6, context=5, minutes_ago=30 * 60)
        _atlas_events(9, agency=6, context=5, minutes_ago=31 * 24 * 60)
        # First as the triggers left them, in the delta; then folded into the hourly and daily
        # rollups, so each of the three branches a window reads is bounded at its end.
        for folded, (window, span) in ((f, w) for f in (False, True)
                                       for w in (('24h', timedelta(hours=24)),
                                                 ('30d', timedelta(days=30)))):
            if folded and window == '24h':
                _sql("SELECT uc_fold_activity_rollups() AS folded", fetch='one')
            with self.subTest(window=window, folded=folded), self._unwithheld():
                d = self._ask('/api/atlas/breakdown?window=%s&dimension=outcome&agencies=6'
                              '&contexts=VOTING&compare=previous' % window)
                prev = d['previous']
                self.assertEqual((prev['until'], prev['incomplete']), (d['since'], None))
                since = datetime.fromisoformat(d['since'])
                before = datetime.fromisoformat(prev['since'])
                self.assertEqual(since - before, span)
                for c in d['categories']:
                    now_n = self._count(6, "context_id = 5 AND outcome = %s AND event_timestamp >= %s",
                                        (c['label'], since))
                    then_n = self._count(6, "context_id = 5 AND outcome = %s AND event_timestamp >= %s "
                                            "AND event_timestamp < %s", (c['label'], before, since))
                    self.assertEqual((c['n_total'], c['prev_total'], c['change']),
                                     (now_n, then_n, now_n - then_n), c['label'])
                by = {c['label']: c for c in d['categories']}
                self.assertGreater(by['FAILURE']['prev_total'] + by['SUCCESS']['prev_total'], 0)

    def test_a_change_is_shown_only_where_both_counts_are(self):
        """Now 6 failures and 8 successes; before 3 failures, 10 successes and 7 expiries. The 3
        is withheld, so the failures' change is too: 6 and a change of 3 would give it back."""
        _atlas_events(6, agency=6, context=6, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(8, agency=6, context=6)
        _atlas_events(3, agency=6, context=6, outcome='FAILURE', disclosure='SELECTIVE',
                      minutes_ago=26 * 60)
        _atlas_events(10, agency=6, context=6, minutes_ago=26 * 60)
        _atlas_events(7, agency=6, context=6, outcome='EXPIRED', disclosure='SELECTIVE',
                      minutes_ago=26 * 60)
        d = self._ask('/api/atlas/breakdown?window=24h&dimension=outcome&agencies=6'
                      '&contexts=MOTOR_VEHICLE&compare=previous')
        got = {c['label']: (c['n_total'], c['prev_total'], c['change']) for c in d['categories']}
        self.assertEqual(got, {'FAILURE': (6, None, None), 'SUCCESS': (8, 10, -2),
                               'EXPIRED': (None, 7, None), 'UNAUTHORIZED': (None, None, None)})

    def test_a_rising_failure_share_is_marked_from_shown_counts_alone(self):
        """Doubled with fifteen more failures is marked; doubled with six more is not, nor is
        eleven more short of double, nor anything beside a withheld count."""
        for context, (s_before, f_before, s_now, f_now) in ((2, (40, 5, 25, 20)),
                                                            (3, (40, 5, 34, 11)),
                                                            (7, (30, 10, 25, 21)),
                                                            (1, (40, 2, 25, 20))):
            _atlas_events(s_before, agency=5, context=context, minutes_ago=26 * 60)
            _atlas_events(f_before, agency=5, context=context, outcome='FAILURE',
                          disclosure='SELECTIVE', minutes_ago=26 * 60)
            _atlas_events(s_now, agency=5, context=context)
            _atlas_events(f_now, agency=5, context=context, outcome='FAILURE', disclosure='SELECTIVE')
        d = self._ask('/api/atlas/breakdown?window=24h&dimension=context&agencies=5&compare=previous')
        rose = {c['label']: c['failure_rose'] for c in d['categories'] if not c.get('folded')}
        self.assertEqual({k: rose[k] for k in ('EMPLOYMENT', 'HEALTHCARE', 'GOVERNMENT_BENEFITS')},
                         {'EMPLOYMENT': True, 'HEALTHCARE': False, 'GOVERNMENT_BENEFITS': False})
        self.assertIsNone(rose['VOTING'], 'no count, no mark')
        # 2 failures before is withheld: 20 now would mark it from a count nobody may see.
        self.assertIsNone(rose['BANKING'], 'a withheld count marks nothing')

    def test_the_cross_tab_compares_each_cell_and_row(self):
        _atlas_events(5, agency=4, context=4)
        _atlas_events(6, agency=4, context=4, outcome='FAILURE', disclosure='SELECTIVE')
        _atlas_events(7, agency=4, context=4, minutes_ago=26 * 60)
        _atlas_events(2, agency=4, context=4, outcome='FAILURE', disclosure='SELECTIVE',
                      minutes_ago=26 * 60)
        with self._unwithheld():
            d = self._ask('/api/atlas/crosstab?window=24h&row=agency&col=outcome&agencies=4'
                          '&compare=previous')
        since = datetime.fromisoformat(d['since'])
        before = datetime.fromisoformat(d['previous']['since'])
        rows = {r['label']: r for r in d['rows']}
        tsa = rows['Transportation Security Admin']
        then_total = self._count(4, "event_timestamp >= %s AND event_timestamp < %s", (before, since))
        self.assertEqual((tsa['prev_total'], tsa['change']),
                         (then_total, tsa['total'] - then_total))
        for c in d['cells']:
            if c['row'] != 'Transportation Security Admin':
                self.assertEqual((c['prev'], c['change']), (None, None), 'the folded row')
                continue
            then_n = self._count(4, "outcome = %s AND event_timestamp >= %s AND event_timestamp < %s",
                                 (c['col'], before, since))
            self.assertEqual((c['prev'], c['change']), (then_n, c['n'] - then_n), c['col'])
        self.assertEqual(rows[atlas_routes._ATLAS_FOLDED]['prev_total'], None)

    def test_nothing_comes_before_all_time(self):
        for path in ('/api/atlas/breakdown?window=all&dimension=outcome&compare=previous',
                     '/api/atlas/crosstab?window=all&row=agency&col=outcome&compare=previous',
                     '/api/atlas/breakdown?window=24h&dimension=outcome&compare=next'):
            with self.subTest(path):
                self.assertIn('error', self._ask(path, status=400))

    def test_purged_hours_are_not_compared(self):
        """A purge deletes the hourly rollup before its cutoff and keeps the daily one. A window
        before reaching past the first hour still held would count less than happened, so when
        the daily rollup holds a day before that hour's, nothing in it is compared."""
        now = self._db_now().replace(minute=0, second=0, microsecond=0)
        url = '/api/atlas/breakdown?window=24h&dimension=outcome&compare=previous'
        with patch.object(atlas_routes, '_first_hour', return_value=now - timedelta(hours=2)), \
                patch.object(atlas_routes, '_first_day', return_value=now - timedelta(days=90)):
            d = self._ask(url)
        self.assertIn('no longer held', d['previous']['incomplete'])
        self.assertTrue(all(c['prev_total'] is None and c['change'] is None
                            for c in d['categories']))
        atlas_routes._atlas_cache_clear()
        # A system that began two hours ago purged nothing: its days start the day its hours do.
        with patch.object(atlas_routes, '_first_hour', return_value=now - timedelta(hours=2)), \
                patch.object(atlas_routes, '_first_day',
                             return_value=(now - timedelta(hours=2)).replace(hour=0)):
            self.assertIsNone(self._ask(url)['previous']['incomplete'])

    def test_a_narrow_window_before_is_noted_and_a_comparison_is_its_own_question(self):
        _atlas_events(60, agency=4, context=2)
        url = '/api/atlas/breakdown?window=24h&dimension=outcome&agencies=4&contexts=EMPLOYMENT'
        self.assertNotIn('previous', self._ask(url), 'not asked, not answered')
        with self.assertLogs(flask_app.app.logger, level='INFO') as logs:
            flask_app.app.logger.info('control')
            d = self._ask(url + '&compare=previous')
        self.assertIn('previous', d, 'the comparison is not the cached answer without it')
        lines = [m for m in logs.output if 'atlas narrow question' in m]
        self.assertEqual(len(lines), 1, 'the window before holds fewer than fifty')
        self.assertIn('compare=previous', lines[0])


class AtlasIntegrityTests(_AtlasCase):
    """The integrity card (lab/strategy/009 A2): the latest state epoch and anchor batch, read
    by their keys, and the Athena board's verdict on this database. Header rows only: no leaf,
    no person, not the operator who closed the epoch; a count in them withheld below five."""

    def test_the_latest_epoch_and_batch_are_read_by_their_keys(self):
        """A new epoch over the sample's credentials, five or more, beside the sample's own: the
        card shows the newer, its count shown."""
        from psycopg2.extras import Json
        admin = _sql("SELECT user_id FROM AppUser WHERE role = 'admin' AND is_active "
                     "ORDER BY user_id LIMIT 1", fetch='one')['user_id']
        tokens = [r['token_id'] for r in _sql("SELECT token_id FROM IdentityToken "
                                              "ORDER BY token_id LIMIT 6")]
        _sql("CALL uc11_close_epoch(%s, %s, %s, %s)",
             ('f' * 64, datetime.now() + timedelta(days=30), admin,
              Json([{'token_id': t, 'leaf_hash': '%02x' % t * 32} for t in tokens])), fetch='none')
        self.assertGreater(_sql("SELECT count(*) AS n FROM TokenStateEpoch", fetch='one')['n'], 1)
        e = _sql("SELECT * FROM TokenStateEpoch ORDER BY epoch_id DESC LIMIT 1", fetch='one')
        self.assertEqual(e['committed_count'], len(tokens))
        self.assertGreaterEqual(len(tokens), 5, 'enough credentials for a count that is shown')
        b = _sql("SELECT * FROM AnchorBatch ORDER BY batch_id DESC LIMIT 1", fetch='one')
        self.assertTrue(e and b, 'the sample has an epoch and a batch')
        with self._unwithheld():
            d = self._ask('/api/atlas/integrity')
        self.assertEqual(d['epoch'], {
            'id': e['epoch_id'], 'closed_at': e['closed_at'].isoformat(timespec='seconds'),
            'valid_from': e['valid_from'].isoformat(timespec='seconds'),
            'valid_until': e['valid_until'].isoformat(timespec='seconds'),
            'expired': False, 'committed': e['committed_count']})
        self.assertEqual(d['anchor'], {
            'id': b['batch_id'], 'created_at': b['created_at'].isoformat(timespec='seconds'),
            'size': b['batch_size'],
            'chain': b['external_chain'] if b['committed_to_chain'] else None,
            'tx': b['external_chain_tx'] if b['committed_to_chain'] else None})

    def test_an_epoch_past_its_validity_reads_expired(self):
        """On the database's clock: the browser's may be wrong, and the verifier's is the
        database's."""
        until = _sql("SELECT valid_until FROM TokenStateEpoch ORDER BY epoch_id DESC LIMIT 1",
                     fetch='one')['valid_until']
        for now, expired in ((until - timedelta(seconds=1), False), (until, True),
                             (until + timedelta(days=1), True)):
            atlas_routes._atlas_cache_clear()
            with patch.object(atlas_routes, '_db_now', return_value=now):
                self.assertEqual(self._ask('/api/atlas/integrity')['epoch']['expired'], expired, now)

    def test_a_count_below_five_is_withheld(self):
        """The sample's epoch commits 3 credentials and its batches hold 1 anchor each."""
        e = _sql("SELECT committed_count FROM TokenStateEpoch ORDER BY epoch_id DESC LIMIT 1",
                 fetch='one')['committed_count']
        b = _sql("SELECT batch_size FROM AnchorBatch ORDER BY batch_id DESC LIMIT 1",
                 fetch='one')['batch_size']
        d = self._ask('/api/atlas/integrity')
        self.assertEqual((d['epoch']['committed'], d['anchor']['size']),
                         (e if e >= 5 else None, b if b >= 5 else None))
        self.assertLess(min(e, b), 5, 'the sample exercises the withholding')

    def test_the_verdict_is_the_boards(self):
        import athena_board
        with flask_app.app.test_request_context('/'):
            states = [r['state'] for r in athena_board.read_board(flask_app.query)['rules']]
        board = self._ask('/api/atlas/integrity')['board']
        self.assertEqual((board['rules'], board['in_force'], board['not_in_force'], board['repository']),
                         (len(states), states.count('in_force'), states.count('not_in_force'),
                          states.count('repository')))
        self.assertGreater(board['in_force'], 0)

    def test_a_rule_not_in_force_reads_so(self):
        import athena_board
        with flask_app.app.test_request_context('/'):
            real = athena_board.read_board(flask_app.query)
        broken = dict(real, rules=[dict(real['rules'][0], state='not_in_force')] + real['rules'][1:])
        with patch.object(athena_board, 'read_board', return_value=broken):
            board = self._ask('/api/atlas/integrity')['board']
        self.assertEqual(board['not_in_force'],
                         [r['state'] for r in broken['rules']].count('not_in_force'))
        self.assertGreaterEqual(board['not_in_force'], 1)

    def test_the_closer_is_not_named(self):
        closer = _sql("SELECT u.username FROM TokenStateEpoch e JOIN AppUser u "
                      "  ON u.user_id = e.closed_by_user_id ORDER BY e.epoch_id DESC LIMIT 1",
                      fetch='one')['username']
        body = self.client.get('/api/atlas/integrity').get_data(as_text=True)
        self.assertNotIn('closed_by', body)
        self.assertNotIn('"%s"' % closer, body)

    def test_the_page_carries_the_card_and_the_control(self):
        body = self.client.get('/atlas').get_data(as_text=True)
        for hook in ('data-ov-integrity', 'href="/athena"', 'data-ov-int-value="board"',
                     'data-ov-int-value="epoch"', 'data-ov-int-value="anchor"',
                     'data-bd-compare="previous"', 'data-bd-metric="change"'):
            self.assertIn(hook, body, hook)


class AtlasReadsNoEventTableTests(PolarisTestCase):
    """The Atlas costs the same at any population because no reader reads an event table
    (lab/strategy/009, step 4): each sums the activity rollups, whose rows number the hours times
    the authorities and contexts active in them. Proved by privilege, not by reading the source:
    the application role loses SELECT on both event tables inside a transaction that is rolled
    back, and every reader still answers. A reader that joined an event table back in, for a
    column the rollups lack, fails here with 'permission denied'."""

    READERS = (
        "atlas_stats(NULL, TRUE)",
        "atlas_stats(LOCALTIMESTAMP - INTERVAL '1 day', FALSE, '3')",
        "atlas_volume_series(LOCALTIMESTAMP - INTERVAL '7 days', FALSE, INTERVAL '4 hours')",
        "atlas_volume_series(LOCALTIMESTAMP - INTERVAL '30 days', TRUE, INTERVAL '1 day', 'lifecycle')",
        "atlas_breakdown('agency', NULL, TRUE, 50)",
        "atlas_breakdown('algorithm', NULL, TRUE, 50)",
        "atlas_breakdown('event_type', NULL, TRUE, 50, 'lifecycle')",
        "atlas_crosstab('agency', 'outcome', NULL, TRUE, 50)",
        "atlas_crosstab('agency', 'event_type', NULL, TRUE, 50, 'lifecycle')",
        "atlas_heatmap(NULL)",
        "atlas_heatmap(NULL, 'lifecycle')",
        "atlas_series_stacked(LOCALTIMESTAMP - INTERVAL '7 days', FALSE, INTERVAL '4 hours', 'context')",
        "atlas_series_stacked(LOCALTIMESTAMP - INTERVAL '7 days', FALSE, INTERVAL '4 hours', 'agency', 'lifecycle')",
        "atlas_agency_facet(NULL, TRUE, 50)",
        "atlas_geo_jurisdictions(NULL, TRUE, 500)",
        "atlas_geo_jurisdictions(NULL, TRUE, 500, 'lifecycle')",
    )

    def test_every_reader_answers_without_the_event_tables(self):
        conn = psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG)
        try:
            with conn.cursor() as cur:
                for reader in self.READERS:
                    with self.subTest(reader):
                        cur.execute("BEGIN")
                        cur.execute("REVOKE SELECT ON VerificationEvent, TokenLifecycleEvent "
                                    "  FROM polaris_app")
                        cur.execute("SET LOCAL ROLE polaris_app")
                        try:
                            cur.execute("SELECT * FROM " + reader)
                            cur.fetchall()
                        finally:
                            cur.execute("ROLLBACK")
                # The control: as the role without SELECT, an event table itself is refused, so
                # the readers' answers above were not a missing grant going unnoticed.
                cur.execute("BEGIN")
                cur.execute("REVOKE SELECT ON VerificationEvent FROM polaris_app")
                cur.execute("SET LOCAL ROLE polaris_app")
                with self.assertRaises(psycopg2.errors.InsufficientPrivilege):
                    cur.execute("SELECT count(*) FROM VerificationEvent")
                cur.execute("ROLLBACK")
        finally:
            conn.close()

    def test_every_reader_is_exercised_here(self):
        """A reader added to 11_atlas.sql without a line above would be the one unproven."""
        defined = {r['proname'] for r in _sql(
            "SELECT DISTINCT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace "
            " WHERE n.nspname = 'public' AND p.proname LIKE %s AND p.proretset", ('atlas\\_%',))}
        called = {r.split('(')[0] for r in self.READERS}
        helpers = {'atlas_verification_cells', 'atlas_lifecycle_cells', 'atlas_verification_matching',
                   'atlas_lifecycle_matching', 'atlas_verification_combos', 'atlas_lifecycle_combos'}
        self.assertEqual(defined - helpers, called)


class AtlasSimulationModeTests(PolarisTestCase):
    """v9.261 (roadmap P2.14 S4): the Atlas live-simulation control streams
    notional national activity through the real verification path so an operator
    watches the console light up. It is dev/demo only: three gates keep it out of
    production — SIM_MODE is force-off under POLARIS_ENV=production, the
    /api/sim/tick route 404s when SIM_MODE is off, and polaris_sim.assert_expendable()
    refuses production on the writer itself. SIM_MODE is read at request time, so
    these tests flip flask_app.SIM_MODE and restore it."""

    def _set_sim_mode(self, on):
        prev = flask_app.SIM_MODE
        flask_app.SIM_MODE = on
        self.addCleanup(setattr, flask_app, 'SIM_MODE', prev)

    def _event_count(self):
        conn = psycopg2.connect(cursor_factory=RealDictCursor, **DB_CONFIG)
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT count(*) AS n FROM VerificationEvent")
                return cur.fetchone()['n']
        finally:
            conn.close()

    def test_control_absent_and_route_404_when_off(self):
        self._set_sim_mode(False)
        self.assertNotIn('data-atlas-sim', self.client.get('/atlas').get_data(as_text=True),
                         "the sim control must NOT render when SIM_MODE is off")
        # A fully valid (logged-in, CSRF-carrying) request still 404s: the route
        # is effectively absent when the gate is off.
        r = self._post('/api/sim/tick', data={'count': '5'}, csrf_from='/uc1/issue')
        self.assertEqual(r.status_code, 404)

    def test_control_renders_when_on(self):
        self._set_sim_mode(True)
        body = self.client.get('/atlas').get_data(as_text=True)
        self.assertIn('data-atlas-sim', body)
        self.assertIn('data-atlas-sim-toggle', body)

    def test_tick_streams_events_through_the_real_path(self):
        self._set_sim_mode(True)
        before = self._event_count()
        r = self._post('/api/sim/tick', data={'count': '30'}, csrf_from='/uc1/issue')
        self.assertEqual(r.status_code, 200)
        data = r.get_json()
        self.assertEqual(data['streamed'], 30)
        self.assertGreaterEqual(data['total_events'], before + 30,
                                "the streamed events must be persisted (real write path)")
        self.assertEqual(self._event_count(), data['total_events'])
        # C6: a zero-knowledge verification is counted but never located; the sim
        # produces a disclosure mix, so ZK rows appear in the tally.
        self.assertIn('by_disclosure', data)

    def test_tick_batch_is_bounded(self):
        self._set_sim_mode(True)
        # A caller asking for far more than the cap gets the cap, not a million rows.
        r = self._post('/api/sim/tick', data={'count': '100000'}, csrf_from='/uc1/issue')
        self.assertEqual(r.status_code, 200)
        self.assertLessEqual(r.get_json()['streamed'], flask_app._SIM_TICK_MAX)

    def test_tick_requires_login(self):
        self._set_sim_mode(True)
        self._logout()
        r = self.client.post('/api/sim/tick', data={'count': '5'})
        self.assertIn(r.status_code, (302, 401))


class HealthEndpointTests(PolarisTestCase):
    """v7: /api/health structured status endpoint."""

    def test_health_returns_200_when_db_up(self):
        # No login required for health
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            r = c.get('/api/health')
        self.assertIn(r.status_code, (200, 503))
        data = r.get_json()
        self.assertIn('status', data)
        self.assertIn(data['status'], ('healthy', 'degraded', 'unhealthy'))
        self.assertIn('checks', data)
        self.assertIn('database', data['checks'])
        self.assertIn('atlas_cache', data['checks'])

    def test_liveness_probe_is_cheap_and_alive(self):
        """v9.108: /api/health/live is the liveness probe — it must answer 200
        with status 'alive' and must NOT run the dependency roll-up (no 'checks'
        key), so a DB/redis outage cannot make it fail and restart the container."""
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            r = c.get('/api/health/live')
        self.assertEqual(r.status_code, 200,
            "liveness must be 200 whenever the process answers")
        data = r.get_json()
        self.assertEqual(data['status'], 'alive')
        self.assertNotIn('checks', data,
            "liveness must be cheap — it must not run the dependency checks")

    def test_readiness_probe_runs_dependency_checks(self):
        """v9.108: /api/health/ready is the readiness probe — it runs the
        dependency roll-up (200 when serviceable, 503 when a critical dependency
        is down) so an orchestrator can stop routing without restarting."""
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            r = c.get('/api/health/ready')
        self.assertIn(r.status_code, (200, 503))
        data = r.get_json()
        self.assertIn('checks', data)
        self.assertIn('database', data['checks'])
        self.assertIn(data['status'], ('healthy', 'degraded', 'unhealthy'))

    def test_health_does_not_require_login(self):
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            # Don't log in
            r = c.get('/api/health')
        # Health is reachable without auth (200/503 valid; 302 redirect to login is NOT)
        self.assertNotEqual(r.status_code, 302,
            "/api/health must not redirect to login")

    def test_health_reports_rate_limiter_backend(self):
        """v7.5 / R8-2: operators need to know which backend is active so
        a multi-worker deployment without Redis is visible (the in-memory
        backend is per-process and the cap is multiplied by worker count)."""
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            r = c.get('/api/health')
        data = r.get_json()
        self.assertIn('redis', data['checks'])
        rl = data['checks']['redis']
        self.assertIn('backend', rl)
        self.assertIn(rl['backend'], ('memory', 'redis'))
        self.assertIn('status', rl)
        self.assertIn(rl['status'], ('healthy', 'degraded', 'unhealthy'))

    def test_health_does_not_leak_paths_or_error_detail(self):
        """The unauthenticated /api/health must not echo absolute filesystem
        paths (the zk binary, the state-dir probe) or raw exception text (which
        embeds the DB host/port/name on a connection error) to anonymous callers
        (CWE-209). The per-component status tokens convey health without the
        detail, which is logged server-side instead."""
        import json
        from app import app as polaris_app
        with polaris_app.test_client() as c:
            r = c.get('/api/health')
        data = r.get_json()
        for name, check in data['checks'].items():
            self.assertNotIn('error', check, f"{name} check leaks raw error text")
            self.assertNotIn('path', check, f"{name} check leaks an absolute path")
            self.assertNotIn('mount_probe', check,
                             f"{name} check leaks the state-dir path")
        # The state-dir probe (present on a healthy disk check before this fix)
        # must not appear anywhere in the serialized body.
        self.assertNotIn('mount_probe', json.dumps(data))

    def test_stats_endpoint_returns_hud_signals(self):
        """The headline the map's corners show: the window's counts and the population's active
        credentials, each withheld below the minimum and exact with it off."""
        data = self.client.get('/api/atlas/stats?window=all').get_json()
        for k in ('n_active_tokens', 'n_failures', 'n_full', 'pq_pct', 'zk_pct', 'n_verifs',
                  'n_lifecycles', 'window', 'since', 'grain', 'min_cell'):
            self.assertIn(k, data)
        active = _sql("SELECT count(*) AS n FROM IdentityToken WHERE status = 'ACTIVE'",
                      fetch='one')['n']
        atlas_routes._atlas_cache_clear()
        with patch.object(atlas_routes, '_ATLAS_MIN_CELL', 0):
            data = self.client.get('/api/atlas/stats?window=all').get_json()
        atlas_routes._atlas_cache_clear()
        self.assertEqual(data['n_active_tokens'], active)
        self.assertTrue(0 <= data['pq_pct'] <= 100, data['pq_pct'])

    def test_atlas_endpoints_require_login(self):
        """Every Atlas route, read from the route table so a new one cannot be left out."""
        with self.client.session_transaction() as sess:
            sess.clear()
        rules = sorted(r.rule for r in flask_app.app.url_map.iter_rules()
                       if r.rule == '/atlas' or r.rule.startswith('/api/atlas/'))
        self.assertGreaterEqual(len(rules), 10)
        for path in rules:
            r = self.client.get(path)
            self.assertIn(r.status_code, (302, 401, 403),
                f"Anonymous access to {path} should be denied, got {r.status_code}")


